/* OKLA English product texts: names, short and full descriptions and specifications of the products, used by okla_i18n.js. */
(window.OKLA_I18N_PRODUCTS=window.OKLA_I18N_PRODUCTS||{}).en=[{"code":"OKL-001","name_cs":"Flipper Zero – kapesní multitool pro elektroniku","name_t":"Flipper Zero – Pocket Multi-Tool for Electronics","short_cs_text":"Flipper Zero spojuje NFC na frekvenci 13,56 MHz a RFID na 125 kHz s vlastním displejem a ovládacími tlačítky. Podporované karty lze prozkoumávat přímo na zařízení a jejich data ukládat na microSD. Rozsah čtení a emulace určuje konkrétní protokol i zabezpečení karty. Vestavěný infračervený přijímač a vysílač umožňují pracovat se signály kompatibilních dálkových ovladačů. Naučené příkazy se ukládají do souborů a následně se vybírají v nabídce přístroje. Flipper tak slouží také jako programovatelný ovladač vlastní elektroniky. Rozhraní GPIO propojuje přístroj s externími obvody a vývojovým příslušenstvím. Otevřený firmware podporuje vlastní aplikace a experimenty s elektronikou. Spolu s microSD vytváří prostor pro samostatné projekty s vlastním ovládáním, uloženými soubory a připojenými periferiemi.","short_t_text":"Flipper Zero combines 13.56 MHz NFC and 125 kHz RFID with its own display and control buttons. Supported cards can be explored directly on the device and their data saved to microSD. What can be read and emulated depends on the specific protocol and on the card's security. The built-in infrared receiver and transmitter let you work with signals from compatible remote controls. Learned commands are saved to files and can then be selected from the device menu. This also makes Flipper a programmable remote for your own electronics. The GPIO interface connects the device to external circuits and development accessories. The open firmware supports custom applications and electronics experiments. Together with microSD, it provides room for standalone projects with their own controls, saved files and connected peripherals.","short_t_html":"\n                            Flipper Zero combines 13.56 MHz NFC and 125 kHz RFID with its own display and control buttons. Supported cards can be explored directly on the device and their data saved to microSD. What can be read and emulated depends on the specific protocol and on the card's security. The built-in infrared receiver and transmitter let you work with signals from compatible remote controls. Learned commands are saved to files and can then be selected from the device menu. This also makes Flipper a programmable remote for your own electronics. The GPIO interface connects the device to external circuits and development accessories. The open firmware supports custom applications and electronics experiments. Together with microSD, it provides room for standalone projects with their own controls, saved files and connected peripherals.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Flipper Zero – Pocket Multi-Tool for Electronics</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>NFC and RFID in a pocket-sized device</h3><p>Flipper Zero combines 13.56 MHz NFC and 125 kHz RFID with its own display and control buttons. Supported cards can be explored directly on the device and their data saved to microSD. What can be read and emulated depends on the specific protocol and on the card's security.</p><p style=\"margin-top:16px\">The two technologies use different frequencies and work with different types of identifiers. Separate menus give access to the relevant functions for the selected interface. The display shows the available information, and the physical buttons let you select saved items without a connected computer. The memory card keeps your files for further work.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-001-function-1.jpg\" alt=\"Flipper Zero – Pocket Multi-Tool for Electronics – NFC and RFID in a pocket-sized device\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Illustrative depiction of the feature</figcaption></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Infrared control</h3><p>The built-in infrared receiver and transmitter let you work with signals from compatible remote controls. Learned commands are saved to files and can then be selected from the device menu. This also makes Flipper a programmable remote for your own electronics.</p><p style=\"margin-top:16px\">Infrared transmission uses pulses of light that are received by the appliance being controlled. Saved commands can be organised by individual remote and recalled from the menu at any time. Both the receiving and transmitting parts are built into the device, so the same unit both captures a supported command and sends it again later.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-001-function-2.jpg\" alt=\"Flipper Zero – Pocket Multi-Tool for Electronics – Infrared control\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Illustrative depiction of the feature</figcaption></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>GPIO and open firmware</h3><p>The GPIO interface connects the device to external circuits and development accessories. The open firmware supports custom applications and electronics experiments. Together with microSD, it provides room for standalone projects with their own controls, saved files and connected peripherals.</p><p style=\"margin-top:16px\">A connected circuit can extend the functionality, depending on its wiring and software support. GPIO carries electrical signals between the device and the peripheral, while the firmware determines how they are processed. Custom applications can therefore combine inputs from external electronics with information on the display and control via the buttons.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-001-function-3.jpg\" alt=\"Flipper Zero – Pocket Multi-Tool for Electronics – GPIO and open firmware\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Illustrative depiction of the feature</figcaption></figure></section></article>\n                            ","params":[["Kategorie:","Elektronické multitooly","Category:","Electronic multitools"],["Výrobce:","Flipper Devices","Manufacturer:","Flipper Devices"],["Kategorie:","Elektronické multitooly","Category:","Electronic multitools"],["Model:","Flipper Zero","Model:","Flipper Zero"],["Typ zařízení:","Kapesní elektronický multitool","Device type:","Pocket electronic multi-tool"],["Ovládání:","Displej a fyzická tlačítka","Controls:","Display and physical buttons"],["Infračervené rozhraní:","Ano","Infrared interface:","Yes"],["NFC:","13,56 MHz, podporované protokoly","NFC:","13,56 MHz, supported protocols"],["RFID:","125 kHz, podporované protokoly","RFID:","125 kHz, supported protocols"],["Rozšíření:","GPIO","Expansion:","GPIO"],["Paměťová karta:","microSD","Memory card:","microSD"],["Software:","Otevřený firmware","Software:","Open firmware"]],"catalog_names":{"Kapesní multitool Flipper Zero":"Flipper Zero Pocket Multi-Tool","Flipper Zero – kapesní multitool pro elektroniku":"Flipper Zero – Pocket Multi-Tool for Electronics"},"catalog_short_cs":"Poznejte elektroniku, kterou běžně používáte, z jiné strany. Flipper Zero spojuje práci s podporovanými rádiovými protokoly, NFC, RFID a infračerveným ovládáním v malém přístroji s vlastním displejem. Hodí se pro výuku, vývoj i testování vašeho vybavení. Nabídku ovládáte přímo na zařízení a vlastní projekty můžete rozšiřovat prostřednictvím GPIO. Otevřený firmware a dokumentace dávají prostor postupovat od hotových funkcí k vlastnímu programu, doma u stolu i při praktických pokusech. Dálkový ovladač, přístupový čip a NFC karta používají různé způsoby komunikace. Flipper Zero vám pomůže podporované systémy prozkoumat a pochopit rozdíly mezi nimi.","catalog_short_t":"See the electronics you use every day from a different angle. Flipper Zero brings together supported radio protocols, NFC, RFID and infrared control in a small device with its own display. It is well suited to learning, development and testing your own equipment. You navigate the menu directly on the device and can expand your own projects via GPIO. The open firmware and documentation let you progress from ready-made functions to your own code, whether at your desk at home or during hands-on experiments. A remote control, an access fob and an NFC card all communicate in different ways. Flipper Zero helps you explore supported systems and understand the differences between them."},{"code":"OKL-002","name_cs":"LILYGO T-Embed CC1101 – vývojová platforma ESP32-S3","name_t":"LILYGO T-Embed CC1101 – ESP32-S3 Development Platform","short_cs_text":"Dvoujádrový ESP32-S3 pracuje s taktem až 240 MHz. Deska má 16 MB flash a 8 MB PSRAM pro vlastní firmware, grafické rozhraní a zpracování dat. Wi-Fi a Bluetooth LE doplňují připojení potřebné pro síťové a mobilní projekty. IPS displej s úhlopříčkou 1,9 palce má rozlišení 320 × 170 pixelů. Otočný enkodér s tlačítkem slouží k procházení nabídek a změně hodnot. Displej i ovládací prvek jsou součástí jednoho kompaktního těla, takže základní uživatelské rozhraní nevyžaduje další panel. Rádiový modul CC1101 doplňuje NFC rozhraní PN532 a infračervená komunikace. Zařízení tvoří programovatelný základ pro různé bezdrátové experimenty. Dostupné funkce a podporované protokoly závisí na nahraném firmwaru a konkrétním osazení platformy.","short_t_text":"The dual-core ESP32-S3 runs at up to 240 MHz. The board has 16 MB of flash and 8 MB of PSRAM for your own firmware, graphical interface and data processing. Wi-Fi and Bluetooth LE provide the connectivity needed for networked and mobile projects. The 1.9-inch IPS display has a resolution of 320 × 170 pixels. A rotary encoder with a push button is used to browse menus and change values. The display and the control are part of one compact body, so a basic user interface needs no additional panel. The CC1101 radio module is complemented by a PN532 NFC interface and infrared communication. The device forms a programmable basis for a variety of wireless experiments. The available functions and supported protocols depend on the installed firmware and the specific components fitted to the platform.","short_t_html":"\n                            The dual-core ESP32-S3 runs at up to 240 MHz. The board has 16 MB of flash and 8 MB of PSRAM for your own firmware, graphical interface and data processing. Wi-Fi and Bluetooth LE provide the connectivity needed for networked and mobile projects. The 1.9-inch IPS display has a resolution of 320 × 170 pixels. A rotary encoder with a push button is used to browse menus and change values. The display and the control are part of one compact body, so a basic user interface needs no additional panel. The CC1101 radio module is complemented by a PN532 NFC interface and infrared communication. The device forms a programmable basis for a variety of wireless experiments. The available functions and supported protocols depend on the installed firmware and the specific components fitted to the platform.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>LILYGO T-Embed CC1101 – ESP32-S3 Development Platform</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>ESP32-S3 processor</h3><p>The dual-core ESP32-S3 runs at up to 240 MHz. The board has 16 MB of flash and 8 MB of PSRAM for your own firmware, graphical interface and data processing. Wi-Fi and Bluetooth LE provide the connectivity needed for networked and mobile projects.</p><p style=\"margin-top:16px\">Flash stores the program and its data, while PSRAM extends the working memory available to the application. This split is useful when working with screens, menus and communication tasks. The integrated wireless interface lets you link local control of the platform with data from a compatible network or device.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-002-function-1.jpg\" alt=\"LILYGO T-Embed CC1101 – ESP32-S3 Development Platform – ESP32-S3 processor\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Colour display and rotary control</h3><p>The 1.9-inch IPS display has a resolution of 320 × 170 pixels. A rotary encoder with a push button is used to browse menus and change values. The display and the control are part of one compact body, so a basic user interface needs no additional panel.</p><p style=\"margin-top:16px\">The wide screen format leaves room for status information, icons and clear menus. Turning the encoder and pressing its button are two separate inputs for the program. The firmware can assign them to moving between items, adjusting settings or confirming a selection, with no need to connect a keyboard.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-002-function-2.jpg\" alt=\"LILYGO T-Embed CC1101 – ESP32-S3 Development Platform – Colour display and rotary control\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>CC1101, NFC and infrared interface</h3><p>The CC1101 radio module is complemented by a PN532 NFC interface and infrared communication. The device forms a programmable basis for a variety of wireless experiments. The available functions and supported protocols depend on the installed firmware and the specific components fitted to the platform.</p><p style=\"margin-top:16px\">Each communication block is a separate interface with its own capabilities and limitations. The radio module handles supported radio communication, the PN532 is used for NFC and the infrared section for optical transmission. Your program can combine their handling with the screen and the rotary control into a single user interface.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-002-function-3.jpg\" alt=\"LILYGO T-Embed CC1101 – ESP32-S3 Development Platform – CC1101, NFC and infrared interface\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Elektronické multitooly","Category:","Electronic multitools"],["Výrobce:","LILYGO","Manufacturer:","LILYGO"],["Kategorie:","Elektronické multitooly","Category:","Electronic multitools"],["Model:","LILYGO T Embed CC1101 ESP32 S3","Model:","LILYGO T Embed CC1101 ESP32 S3"],["Displej:","1,9″ IPS TFT, ST7789V","Display:","1,9″ IPS TFT, ST7789V"],["Procesor:","ESP32-S3, dvoujádrový LX7","Processor:","ESP32-S3, dual-core LX7"],["Takt procesoru:","Až 240 MHz","Processor clock speed:","Up to 240 MHz"],["Flash:","16 MB","Flash:","16 MB"],["PSRAM:","8 MB","PSRAM:","8 MB"],["Rozlišení displeje:","320 × 170 px","Display resolution:","320 × 170 px"],["Wi-Fi:","2,4 GHz, 802.11 b/g/n","Wi-Fi:","2,4 GHz, 802.11 b/g/n"],["Bluetooth:","5.0 LE","Bluetooth:","5.0 LE"],["Rádiový modul:","CC1101","Radio module:","CC1101"],["NFC modul:","PN532","NFC module:","PN532"],["Připojení:","USB-C","Connectivity:","USB-C"],["Ovládání:","Otočný enkodér","Controls:","Rotary encoder"],["Paměťová karta:","TF / microSD","Memory card:","TF / microSD"]],"catalog_names":{"Multifunkční vývojová platforma LILYGO T Embed CC1101 ESP32 S3":"LILYGO T Embed CC1101 ESP32 S3 Multifunctional Development Platform","LILYGO T-Embed CC1101 – vývojová platforma ESP32-S3":"LILYGO T-Embed CC1101 – ESP32-S3 Development Platform"},"catalog_short_cs":"Postavte vlastní ovládací panel, bezdrátový experiment nebo rozhraní pro chytrou elektroniku. LILYGO T-Embed CC1101 propojuje procesor ESP32-S3, rádiový modul CC1101, barevný displej a otočný ovladač v kompaktní vývojové platformě. Místo skládání základních částí z několika desek získáte přehledný základ pro vlastní firmware. Hodnoty, nabídky a stav programu můžete sledovat přímo na zařízení. Praktické řešení pro výuku, rychlé prototypy i aplikace, jejichž ovládání chcete mít po ruce. Dvoujádrový procesor tvoří základ pro ovládací rozhraní, vyhodnocování vstupů a komunikaci. Platformu lze programovat pomocí běžných nástrojů pro ESP32 a začít na ukázkách výrobce.","catalog_short_t":"Build your own control panel, wireless experiment or interface for smart electronics. LILYGO T-Embed CC1101 combines an ESP32-S3 processor, a CC1101 radio module, a colour display and a rotary control in a compact development platform. Instead of assembling the basic parts from several boards, you get a tidy foundation for your own firmware. Values, menus and program status can be monitored directly on the device. A practical solution for teaching, rapid prototyping and applications whose controls you want close at hand. The dual-core processor provides the basis for the control interface, input evaluation and communication. The platform can be programmed with the usual ESP32 tools, and you can start from the manufacturer's examples."},{"code":"OKL-003","name_cs":"LILYGO T-Deck Plus – kapesní komunikátor ESP32","name_t":"LILYGO T-Deck Plus – Pocket ESP32 Communicator","short_cs_text":"T-Deck Plus má vlastní klávesnici pro zadávání textu, příkazů a hodnot. Trackball doplňuje ovládání nabídky a pohyb v rozhraní. Vstupní prvky lze použít ve vlastním firmwaru pro přenosný terminál, komunikátor nebo ovládací panel. Barevný panel s rozlišením 320 × 240 pixelů zobrazuje text, aktuální hodnoty i jednoduchou grafiku. Dotykové ovládání lze kombinovat s klávesnicí a trackballem. Procesor ESP32-S3 poskytuje základ pro vlastní aplikace i bezdrátové připojení. Verze Plus zahrnuje GPS a vestavěnou baterii pro přenosné projekty. Polohové údaje může vlastní program spojit s informacemi na displeji. Rozhraní a dostupné piny vycházejí ze zapojení verze Plus; GPS v této variantě využívá piny konektoru Grove.","short_t_text":"T-Deck Plus has its own keyboard for entering text, commands and values. A trackball complements menu control and navigation within the interface. The input elements can be used in your own firmware for a portable terminal, communicator or control panel. The colour panel with a resolution of 320 × 240 pixels shows text, current values and simple graphics. Touch control can be combined with the keyboard and trackball. The ESP32-S3 processor provides the basis for your own applications and wireless connectivity. The Plus version includes GPS and a built-in battery for portable projects. Your own program can combine location data with information on the display. The interfaces and available pins follow the Plus version's wiring; in this variant, the GPS uses the pins of the Grove connector.","short_t_html":"\n                            T-Deck Plus has its own keyboard for entering text, commands and values. A trackball complements menu control and navigation within the interface. The input elements can be used in your own firmware for a portable terminal, communicator or control panel. The colour panel with a resolution of 320 × 240 pixels shows text, current values and simple graphics. Touch control can be combined with the keyboard and trackball. The ESP32-S3 processor provides the basis for your own applications and wireless connectivity. The Plus version includes GPS and a built-in battery for portable projects. Your own program can combine location data with information on the display. The interfaces and available pins follow the Plus version's wiring; in this variant, the GPS uses the pins of the Grove connector.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>LILYGO T-Deck Plus – Pocket ESP32 Communicator</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Physical keyboard and trackball</h3><p>T-Deck Plus has its own keyboard for entering text, commands and values. A trackball complements menu control and navigation within the interface. The input elements can be used in your own firmware for a portable terminal, communicator or control panel.</p><p style=\"margin-top:16px\">Dedicated keys allow characters to be typed directly, without an on-screen keyboard covering the whole display. The screen therefore remains free for application content. The trackball provides an additional input whose function is defined by the program, complementing text entry with moving between items or controlling a cursor.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-003-function-1.jpg\" alt=\"LILYGO T-Deck Plus – Pocket ESP32 Communicator – Physical keyboard and trackball\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>2.8-inch touch display</h3><p>The colour panel with a resolution of 320 × 240 pixels shows text, current values and simple graphics. Touch control can be combined with the keyboard and trackball. The ESP32-S3 processor provides the basis for your own applications and wireless connectivity.</p><p style=\"margin-top:16px\">The panel resolution defines the space available for the application's graphical elements and rendered text. The touch layer provides direct input from the screen surface, while the physical keyboard keeps a separate path for typing. Your own interface can combine these control methods to suit the data being displayed.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-003-function-2.jpg\" alt=\"LILYGO T-Deck Plus – Pocket ESP32 Communicator – 2.8-inch touch display\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>GPS and built-in battery</h3><p>The Plus version includes GPS and a built-in battery for portable projects. Your own program can combine location data with information on the display. The interfaces and available pins follow the Plus version's wiring; in this variant, the GPS uses the pins of the Grove connector.</p><p style=\"margin-top:16px\">The GPS supplies location data to the application, while the battery lets you use the device without a permanently connected power cable. Displaying the position and making further use of it is handled by the installed software. Pin sharing in this version is part of the hardware design and affects the options for connecting other peripherals at the same time.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-003-function-3.jpg\" alt=\"LILYGO T-Deck Plus – Pocket ESP32 Communicator – GPS and built-in battery\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Elektronické multitooly","Category:","Electronic multitools"],["Výrobce:","LILYGO","Manufacturer:","LILYGO"],["Kategorie:","Elektronické multitooly","Category:","Electronic multitools"],["Model:","LILYGO T Deck Plus","Model:","LILYGO T Deck Plus"],["Displej:","2,8″ LCD, ST7789","Display:","2,8″ LCD, ST7789"],["Procesor:","ESP32-S3","Processor:","ESP32-S3"],["Flash:","16 MB","Flash:","16 MB"],["PSRAM:","8 MB","PSRAM:","8 MB"],["Rozlišení displeje:","320 × 240 px","Display resolution:","320 × 240 px"],["Dotykové ovládání:","Kapacitní, GT911","Touch control:","Capacitive, GT911"],["Další ovládání:","Fyzická klávesnice a trackball","Additional controls:","Physical keyboard and trackball"],["GPS modul:","MIA-M10Q","GPS module:","MIA-M10Q"],["Bluetooth:","5.0 LE","Bluetooth:","5.0 LE"],["Wi-Fi:","2,4 GHz","Wi-Fi:","2,4 GHz"],["Připojení:","USB-C","Connectivity:","USB-C"],["Paměťová karta:","TF / microSD","Memory card:","TF / microSD"],["Baterie:","2000 mAh","Battery:","2000 mAh"]],"catalog_names":{"Kapesní ESP32 komunikátor LILYGO T Deck Plus":"LILYGO T Deck Plus Pocket ESP32 Communicator","LILYGO T-Deck Plus – kapesní komunikátor ESP32":"LILYGO T-Deck Plus – Pocket ESP32 Communicator"},"catalog_short_cs":"Vytvořte vlastní přenosný terminál, datový panel nebo IoT rozhraní s pohodlnějším zadáváním. LILYGO T-Deck Plus kombinuje platformu ESP32-S3 s fyzickou klávesnicí, dotykovým displejem a trackballem. Text, stav aplikace a její ovládání tak máte přímo na zařízení bez trvale připojeného počítače. GPS přidává možnosti práce s polohovými daty a vestavěná baterie podporuje přenosné projekty. Konkrétní bezdrátové funkce závisejí na variantě a nahraném firmwaru. Krátký text, příkaz nebo změna nastavení se zadávají přehledněji na fyzické klávesnici než několika tlačítky. T-Deck Plus proto dává smysl při návrhu vlastních terminálů a ovládacích rozhraní.","catalog_short_t":"Create your own portable terminal, data panel or IoT interface with more comfortable input. LILYGO T-Deck Plus combines the ESP32-S3 platform with a physical keyboard, a touch display and a trackball. Text, application status and controls are all right on the device, with no permanently connected computer. GPS adds the option of working with location data, and the built-in battery supports portable projects. The specific wireless features depend on the variant and the installed firmware. A short text, a command or a settings change is easier to enter on a physical keyboard than with a handful of buttons. That is why T-Deck Plus makes sense when designing your own terminals and control interfaces."},{"code":"OKL-004","name_cs":"M5Stack Cardputer ADV – mini počítač s klávesnicí","name_t":"M5Stack Cardputer ADV – Mini Computer with Keyboard","short_cs_text":"Cardputer ADV staví na procesoru ESP32-S3 a modulu Stamp-S3A. Klávesnice, displej a napájení jsou integrovány do malého zařízení pro vlastní embedded aplikace. Platforma podporuje programování prostřednictvím nástrojů výrobce včetně Arduino a UiFlow2. Klávesnice s 56 tlačítky doplňuje barevný 1,14palcový displej s rozlišením 240 × 135 pixelů. Audio kodek, mikrofon a reproduktor rozšiřují aplikace o záznam a zvukovou odezvu. Vstupy a výstupy jsou dostupné v jednom přenosném celku. Grove, rozšiřující sběrnice a microSD propojují Cardputer ADV s příslušenstvím a soubory. Připojené moduly mohou poskytovat data pro zobrazení nebo další zpracování. Boční konektory zůstávají přístupné i při používání klávesnice a displeje.","short_t_text":"Cardputer ADV is built around the ESP32-S3 processor and the Stamp-S3A module. The keyboard, display and power supply are integrated into a small device for your own embedded applications. The platform supports programming with the manufacturer's tools, including Arduino and UiFlow2. A 56-key keyboard is complemented by a 1.14-inch colour display with a resolution of 240 × 135 pixels. An audio codec, microphone and speaker add recording and audio feedback to your applications. Inputs and outputs are all available in one portable unit. Grove, an expansion bus and microSD connect Cardputer ADV to accessories and files. Connected modules can supply data for display or further processing. The side connectors remain accessible while you use the keyboard and display.","short_t_html":"\n                            Cardputer ADV is built around the ESP32-S3 processor and the Stamp-S3A module. The keyboard, display and power supply are integrated into a small device for your own embedded applications. The platform supports programming with the manufacturer's tools, including Arduino and UiFlow2. A 56-key keyboard is complemented by a 1.14-inch colour display with a resolution of 240 × 135 pixels. An audio codec, microphone and speaker add recording and audio feedback to your applications. Inputs and outputs are all available in one portable unit. Grove, an expansion bus and microSD connect Cardputer ADV to accessories and files. Connected modules can supply data for display or further processing. The side connectors remain accessible while you use the keyboard and display.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>M5Stack Cardputer ADV – Mini Computer with Keyboard</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>ESP32-S3 in a standalone mini computer</h3><p>Cardputer ADV is built around the ESP32-S3 processor and the Stamp-S3A module. The keyboard, display and power supply are integrated into a small device for your own embedded applications. The platform supports programming with the manufacturer's tools, including Arduino and UiFlow2.</p><p style=\"margin-top:16px\">Your own program can accept text from the keyboard, process it and show the result on the built-in display. The wireless capabilities of the ESP32-S3 extend this foundation with communication with supported devices. The integrated design combines the computing part and user inputs, with no need to assemble a complete control panel from separate parts.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-004-function-1.jpg\" alt=\"M5Stack Cardputer ADV – Mini Computer with Keyboard – ESP32-S3 in a standalone mini computer\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Keyboard, display and sound</h3><p>A 56-key keyboard is complemented by a 1.14-inch colour display with a resolution of 240 × 135 pixels. An audio codec, microphone and speaker add recording and audio feedback to your applications. Inputs and outputs are all available in one portable unit.</p><p style=\"margin-top:16px\">The display is used for short texts, menus and status information. The microphone provides audio input and the speaker audio output for a supported application. Routed through the audio section, they let you work with sound as another component of your program alongside the visual output and the physical keys.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-004-function-2.jpg\" alt=\"M5Stack Cardputer ADV – Mini Computer with Keyboard – Keyboard, display and sound\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Connectors and expansion</h3><p>Grove, an expansion bus and microSD connect Cardputer ADV to accessories and files. Connected modules can supply data for display or further processing. The side connectors remain accessible while you use the keyboard and display.</p><p style=\"margin-top:16px\">The memory card provides file storage separate from the program itself. Connected accessories can supply additional input data or extend the outputs, depending on the wiring and software support. The combination of connectors, keyboard and screen gives your project its own control interface, even when external electronic modules are used.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-004-function-3.jpg\" alt=\"M5Stack Cardputer ADV – Mini Computer with Keyboard – Connectors and expansion\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Elektronické multitooly","Category:","Electronic multitools"],["Výrobce:","M5Stack","Manufacturer:","M5Stack"],["Kategorie:","Elektronické multitooly","Category:","Electronic multitools"],["Model:","M5Stack Cardputer ADV","Model:","M5Stack Cardputer ADV"],["Klávesnice:","56 kláves, 4 × 14","Keyboard:","56 keys, 4 × 14"],["Displej:","1,14″ LCD, ST7789V2","Display:","1,14″ LCD, ST7789V2"],["Procesor:","ESP32-S3FN8, Stamp-S3A","Processor:","ESP32-S3FN8, Stamp-S3A"],["Takt procesoru:","Až 240 MHz","Processor clock speed:","Up to 240 MHz"],["Flash:","8 MB","Flash:","8 MB"],["Rozlišení displeje:","240 × 135 px","Display resolution:","240 × 135 px"],["Paměťová karta:","microSD","Memory card:","microSD"],["Audio kodek:","ES8311","Audio codec:","ES8311"],["Pohybový senzor:","BMI270, 6 os","Motion sensor:","BMI270, 6-axis"],["Rozšíření:","Grove HY2.0-4P a EXT 2.54-14P","Expansion:","Grove HY2.0-4P and EXT 2.54-14P"],["Infračervené rozhraní:","Vysílač","Infrared interface:","Transmitter"],["Vývojová prostředí:","Arduino, UiFlow2, ESP-IDF, PlatformIO","Development environments:","Arduino, UiFlow2, ESP-IDF, PlatformIO"]],"catalog_names":{"Programovatelný mini počítač M5Stack Cardputer ADV":"M5Stack Cardputer ADV Programmable Mini Computer","M5Stack Cardputer ADV – mini počítač s klávesnicí":"M5Stack Cardputer ADV – Mini Computer with Keyboard"},"catalog_short_cs":"Malé zařízení pro velký prostor vlastním nápadům. M5Stack Cardputer ADV spojuje platformu ESP32-S3, barevný displej a 56klávesovou klávesnici v přenosném vývojovém počítači. Hodí se pro vlastní terminály, jednoduché ovládací aplikace a experimenty s elektronikou. Vstup i výstup máte přímo na zařízení, takže nemusíte každou akci zadávat z notebooku. Rozšiřující rozhraní, zvukové prvky a microSD pak umožňují postupně rozvíjet program podle potřeb projektu. Cardputer ADV se hodí tam, kde chcete samostatné rozhraní s možností psát text. Procesor ESP32-S3 tvoří základ vlastního programu a klávesnice usnadňuje zadávání příkazů nebo hodnot.","catalog_short_t":"A small device with plenty of room for your own ideas. M5Stack Cardputer ADV combines the ESP32-S3 platform, a colour display and a 56-key keyboard in a portable development computer. It is ideal for custom terminals, simple control applications and electronics experiments. Input and output are right on the device, so you do not have to enter every action from a laptop. Expansion interfaces, audio components and microSD then let you develop your program step by step to suit the needs of your project. Cardputer ADV is a good fit wherever you want a standalone interface with the ability to type text. The ESP32-S3 processor forms the basis of your own program, and the keyboard makes entering commands or values easy."},{"code":"OKL-005","name_cs":"Vývojová sada ESP32 pro IoT projekty","name_t":"ESP32 Development Kit for IoT Projects","short_cs_text":"Základem sady je vývojová deska ESP32 s bezdrátovou komunikací. Vlastní program zpracovává vstupy a ovládá připojené prvky. Deska umožňuje spojit elektronické zapojení s komunikací přes Wi-Fi nebo Bluetooth. Sada sdružuje vývojovou desku, propojovací vodiče a elektronické prvky pro sestavování výukových obvodů. Nepájivé pole umožňuje měnit zapojení bez trvalého pájeného spoje. Jednotlivé součásti vytvářejí základ pro práci s digitálními vstupy, výstupy a periferiemi. Desku lze kombinovat s kompatibilními senzory, indikačními prvky a dalšími moduly. Program určuje reakce obvodu a podobu získaných dat. Zapojení se může měnit mezi jednotlivými projekty a stejný základ tak poslouží při výuce elektroniky i návrhu IoT prototypu.","short_t_text":"At the heart of the kit is an ESP32 development board with wireless communication. Your own program processes inputs and controls the connected components. The board lets you combine an electronic circuit with communication over Wi-Fi or Bluetooth. The kit brings together a development board, jumper wires and electronic components for building learning circuits. A solderless breadboard lets you change the wiring without permanent soldered joints. The individual components provide a basis for working with digital inputs, outputs and peripherals. The board can be combined with compatible sensors, indicators and other modules. The program determines how the circuit responds and what form the collected data takes. The wiring can change from project to project, so the same foundation serves both for learning electronics and for designing an IoT prototype.","short_t_html":"\n                            At the heart of the kit is an ESP32 development board with wireless communication. Your own program processes inputs and controls the connected components. The board lets you combine an electronic circuit with communication over Wi-Fi or Bluetooth. The kit brings together a development board, jumper wires and electronic components for building learning circuits. A solderless breadboard lets you change the wiring without permanent soldered joints. The individual components provide a basis for working with digital inputs, outputs and peripherals. The board can be combined with compatible sensors, indicators and other modules. The program determines how the circuit responds and what form the collected data takes. The wiring can change from project to project, so the same foundation serves both for learning electronics and for designing an IoT prototype.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>ESP32 Development Kit for IoT Projects</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Programmable ESP32 board</h3><p>At the heart of the kit is an ESP32 development board with wireless communication. Your own program processes inputs and controls the connected components. The board lets you combine an electronic circuit with communication over Wi-Fi or Bluetooth.</p><p style=\"margin-top:16px\">The control program links the state of the input pins to the desired response of the outputs. The wireless section can pass data to another device or receive supported commands. A single project can therefore include both a local electronic circuit and network communication, with the resulting behaviour determined by the chosen firmware.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-005-function-1.jpg\" alt=\"ESP32 Development Kit for IoT Projects – Programmable ESP32 board\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Components for hands-on experiments</h3><p>The kit brings together a development board, jumper wires and electronic components for building learning circuits. A solderless breadboard lets you change the wiring without permanent soldered joints. The individual components provide a basis for working with digital inputs, outputs and peripherals.</p><p style=\"margin-top:16px\">The breadboard connects inserted leads and wires through internal conductive strips. Circuits can be taken apart, and individual parts can be moved between experiments. The wires connect the board to the circuit, while the specific electronic components determine what the assembled circuit does.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-005-function-2.jpg\" alt=\"ESP32 Development Kit for IoT Projects – Components for hands-on experiments\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Modular project design</h3><p>The board can be combined with compatible sensors, indicators and other modules. The program determines how the circuit responds and what form the collected data takes. The wiring can change from project to project, so the same foundation serves both for learning electronics and for designing an IoT prototype.</p><p style=\"margin-top:16px\">A modular approach lets you develop a project gradually, from a simple circuit to a setup with multiple inputs and outputs. The program can combine measured values, signalling and data transfer in a single run. The scope of the project depends on the connected components, their electrical compatibility and the resources available on the board.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-005-function-3.jpg\" alt=\"ESP32 Development Kit for IoT Projects – Modular project design\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Elektronické multitooly","Category:","Electronic multitools"],["Kategorie:","Elektronické multitooly","Category:","Electronic multitools"],["Typ produktu:","Vývojová sada","Product type:","Development kit"],["Platforma:","ESP32","Platform:","ESP32"],["Určení:","Výuka elektroniky a programování","Intended use:","Learning electronics and programming"],["Způsob použití:","Vlastní firmware a zapojení","How it is used:","Custom firmware and wiring"],["Oblast projektů:","IoT a automatizace","Project area:","IoT and automation"],["Provedení:","Sada pro prototypování","Design:","Prototyping kit"]],"catalog_names":{"Vývojová sada ESP32 pro IoT projekty":"ESP32 Development Kit for IoT Projects"},"catalog_short_cs":"Začněte s elektronikou na úlohách, jejichž výsledek hned uvidíte. Vývojová sada ESP32 tvoří základ pro programování mikrokontroléru, práci se vstupy a vlastní IoT prototypy. Využijete ji při domácím studiu, ve školní výuce i při ověřování nápadů na automatizaci. Postupným propojováním programu a zapojení získáte zkušenosti použitelné u dalších zařízení. Konkrétní úlohy, napájení i možnosti připojení se řídí dodanou deskou a skutečným obsahem zvolené varianty sady. Začněte úlohou, u které rozumíte každému kroku: krátký program, kompatibilní součástka a srozumitelná reakce na změnu vstupu. Při dalším pokusu přidejte jedinou novou funkci.","catalog_short_t":"Get started with electronics through tasks whose results you see straight away. The ESP32 development kit is a foundation for programming a microcontroller, working with inputs and building your own IoT prototypes. Use it for self-study at home, in the classroom or to test automation ideas. By gradually combining code and circuits, you gain experience you can apply to other devices. The specific tasks, power supply and connection options depend on the board supplied and the actual contents of the kit variant you choose. Start with a task where you understand every step: a short program, a compatible component and a clear response to a change in input. In the next experiment, add just one new feature."},{"code":"OKL-006","name_cs":"Chytré brýle WAI4 s AI","name_t":"WAI4 Smart Glasses with AI","short_cs_text":"WAI4 spojuje brýlové provedení s elektronikou určenou k propojení s kompatibilním telefonem. Černá obruba zachovává podobu běžného nositelného doplňku. Ovládací a elektronické části jsou součástí konstrukce brýlí. Doprovodný software zajišťuje propojení funkcí brýlí s telefonem. Dostupné AI nástroje vycházejí z konkrétní aplikace, její verze a připojených služeb. Výpočty a nabídka funkcí proto nejsou dány samotným vzhledem obruby. Součásti zařízení jsou rozloženy do obruby a stranic. Brýle ponechávají ruce volné a základní elektroniku nesou přímo na hlavě. Konstrukce tohoto typu se používá jako příslušenství k telefonu; nezahrnuje automaticky zobrazování rozšířené reality před očima.","short_t_text":"WAI4 combines a glasses design with electronics intended for pairing with a compatible phone. The black frame keeps the look of an everyday wearable accessory. The controls and electronic components are built into the structure of the glasses. The companion software links the functions of the glasses with your phone. The AI tools available depend on the specific app, its version and the connected services. Processing and the range of features are therefore not determined by the frame itself. The device's components are distributed across the frame and the temples. The glasses keep your hands free and carry the core electronics directly on your head. A design of this type is used as a phone accessory; it does not automatically include an augmented reality display in front of your eyes.","short_t_html":"\n                            WAI4 combines a glasses design with electronics intended for pairing with a compatible phone. The black frame keeps the look of an everyday wearable accessory. The controls and electronic components are built into the structure of the glasses. The companion software links the functions of the glasses with your phone. The AI tools available depend on the specific app, its version and the connected services. Processing and the range of features are therefore not determined by the frame itself. The device's components are distributed across the frame and the temples. The glasses keep your hands free and carry the core electronics directly on your head. A design of this type is used as a phone accessory; it does not automatically include an augmented reality display in front of your eyes.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>WAI4 Smart Glasses with AI</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Electronics in a glasses frame</h3><p>WAI4 combines a glasses design with electronics intended for pairing with a compatible phone. The black frame keeps the look of an everyday wearable accessory. The controls and electronic components are built into the structure of the glasses.</p><p style=\"margin-top:16px\">The design brings the supporting frame and the functional electronics together in a single item. The phone remains the companion device for supported digital features. Distributing the components across the body of the glasses means they can be worn without a separate holder, while the controls on the frame stay directly accessible.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-006-function-1.jpg\" alt=\"WAI4 Smart Glasses with AI – Electronics in a glasses frame\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Illustrative depiction of the feature</figcaption></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Working with your mobile device</h3><p>The companion software links the functions of the glasses with your phone. The AI tools available depend on the specific app, its version and the connected services. Processing and the range of features are therefore not determined by the frame itself.</p><p style=\"margin-top:16px\">The app acts as the interface between the connected accessory and the available services. Depending on the implementation, individual features may use processing on the phone or a linked online environment. Language options and the range of tools are properties of the software in use, so they may vary between versions and service settings.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-006-function-2.jpg\" alt=\"WAI4 Smart Glasses with AI – Working with your mobile device\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Illustrative depiction of the feature</figcaption></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Compact wearable design</h3><p>The device's components are distributed across the frame and the temples. The glasses keep your hands free and carry the core electronics directly on your head. A design of this type is used as a phone accessory; it does not automatically include an augmented reality display in front of your eyes.</p><p style=\"margin-top:16px\">The wearable design moves the accessory from your hand into the familiar format of glasses. The temples also provide space for the built-in components and their connections. The glasses and phone work as connected parts of one setup, in which the available software determines which tasks can actually be performed.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-006-function-3.jpg\" alt=\"WAI4 Smart Glasses with AI – Compact wearable design\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Illustrative depiction of the feature</figcaption></figure></section></article>\n                            ","params":[["Kategorie:","Chytrá elektronika","Category:","Smart electronics"],["Kategorie:","Chytrá elektronika","Category:","Smart electronics"],["Model:","WAI4","Model:","WAI4"],["Typ zařízení:","Chytré brýle","Device type:","Smart glasses"],["Provedení:","Nositelné brýlové příslušenství","Design:","Wearable glasses accessory"],["Spolupracující zařízení:","Kompatibilní mobilní telefon","Companion device:","Compatible mobile phone"],["AI funkce:","Podle aplikace a dostupné služby","AI features:","Depends on the app and the available service"],["Oblast použití:","Každodenní chytré příslušenství","Use:","Everyday smart accessory"]],"catalog_names":{"Chytré brýle WAI4 s AI":"WAI4 Smart Glasses with AI"},"catalog_short_cs":"Vyzkoušejte nositelnou elektroniku v podobě každodenního doplňku. Chytré brýle WAI4 spojují brýlové provedení s elektronikou a použitím s kompatibilním telefonem. Jsou zajímavou volbou pro zájemce o jinou podobu chytrého příslušenství. Dostupné AI funkce se odvíjejí od aplikace, jazyka, připojení a podmínek poskytované služby. Při výběru proto posuzujte pohodlí obrub společně s podporou funkcí, které chcete skutečně využívat. Důležitý je soulad brýlí, telefonu a softwaru. Brýle představují jinou podobu nositelné elektroniky než hodinky nebo sluchátka. Záleží na jejich vzhledu, usazení a způsobu, jakým je chcete zapojit do běžného dne.","catalog_short_t":"Try wearable electronics in the form of an everyday accessory. WAI4 smart glasses combine a glasses design with electronics and use alongside a compatible phone. They are an interesting choice for anyone looking for a different kind of smart accessory. The AI features available depend on the app, language, connection and the terms of the service provided. When choosing, consider the comfort of the frame together with support for the features you actually want to use. What matters is that the glasses, phone and software work well together. Glasses are a different kind of wearable electronics from a watch or earphones. Their look, fit and the way you want to use them in your daily routine all count."},{"code":"OKL-007","name_cs":"Esaker G300 – chytré brýle","name_t":"Esaker G300 – Smart Glasses","short_cs_text":"G300 nabízí nositelnou elektroniku v klasickém brýlovém tvaru. Funkční části jsou integrovány do obruby a stranic. Propojení s kompatibilním mobilním zařízením rozšiřuje možnosti běžného příslušenství k telefonu. Podporované funkce využívají doprovodný software a připojení k telefonu. Rozsah AI služeb a jejich dostupnost závisí na konkrétní aplikaci. Brýlové provedení umožňuje mít příslušenství při sobě bez držení dalšího zařízení v ruce. Čelní část, stranice a ovládání tvoří jeden celek. Elektronika je začleněna do konstrukce, která zůstává vizuálně blízká běžným brýlím. Konkrétní provedení čoček a dostupné funkce odpovídají dodané variantě G300.","short_t_text":"G300 offers wearable electronics in a classic glasses shape. The functional parts are integrated into the frame and temples. Pairing with a compatible mobile device extends what an ordinary phone accessory can do. Supported features rely on the companion software and the connection to your phone. The scope and availability of AI services depend on the specific app. The glasses design lets you keep the accessory with you without holding another device in your hand. The front, temples and controls form a single unit. The electronics are built into a design that stays visually close to ordinary glasses. The specific lens type and available features correspond to the G300 variant supplied.","short_t_html":"\n                            G300 offers wearable electronics in a classic glasses shape. The functional parts are integrated into the frame and temples. Pairing with a compatible mobile device extends what an ordinary phone accessory can do. Supported features rely on the companion software and the connection to your phone. The scope and availability of AI services depend on the specific app. The glasses design lets you keep the accessory with you without holding another device in your hand. The front, temples and controls form a single unit. The electronics are built into a design that stays visually close to ordinary glasses. The specific lens type and available features correspond to the G300 variant supplied.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Esaker G300 – Smart Glasses</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Esaker G300 Smart Glasses</h3><p>G300 offers wearable electronics in a classic glasses shape. The functional parts are integrated into the frame and temples. Pairing with a compatible mobile device extends what an ordinary phone accessory can do.</p><p style=\"margin-top:16px\">The frame mechanically holds the individual parts together while also carrying the device's integrated components. The temples provide additional space for electronics outside the front of the glasses. G300 thus combines the role of a wearable accessory with the capabilities of a connected phone, through which the supported digital features are made available.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-007-function-1.jpg\" alt=\"Esaker G300 – Smart Glasses – Esaker G300 Smart Glasses\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Mobile software and connectivity</h3><p>Supported features rely on the companion software and the connection to your phone. The scope and availability of AI services depend on the specific app. The glasses design lets you keep the accessory with you without holding another device in your hand.</p><p style=\"margin-top:16px\">The mobile part of the setup provides the software environment for processing and controlling the available features. Support for a particular service is determined by its compatibility with the glasses and the operating system in use. The range of capabilities therefore depends on the whole combination of device and app, including the settings and availability of linked services.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-007-function-2.jpg\" alt=\"Esaker G300 – Smart Glasses – Mobile software and connectivity\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Frame with integrated components</h3><p>The front, temples and controls form a single unit. The electronics are built into a design that stays visually close to ordinary glasses. The specific lens type and available features correspond to the G300 variant supplied.</p><p style=\"margin-top:16px\">The integrated layout keeps the controls and functional parts directly on the wearable frame. The outer shape remains compact and needs no separate housing for the electronics when worn. The lenses are part of the specific version, while the connected digital features are tied to a supported phone and the relevant software.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-007-function-3.jpg\" alt=\"Esaker G300 – Smart Glasses – Frame with integrated components\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Chytrá elektronika","Category:","Smart electronics"],["Kategorie:","Chytrá elektronika","Category:","Smart electronics"],["Model:","G300","Model:","G300"],["Typ produktu:","Chytré brýle","Product type:","Smart glasses"],["Značka:","Esaker","Brand:","Esaker"],["Provedení:","Nositelné elektronické příslušenství","Design:","Wearable electronic accessory"],["Spolupracující zařízení:","Kompatibilní mobilní zařízení","Companion device:","Compatible mobile device"],["Softwarové funkce:","Podle varianty a aplikace","Software features:","Depends on the variant and app"]],"catalog_names":{"Chytré brýle Esaker G300":"Esaker G300 Smart Glasses","Esaker G300 – chytré brýle":"Esaker G300 – Smart Glasses"},"catalog_short_cs":"Klasický tvar brýlí může být také součástí chytré výbavy. Esaker G300 je nositelné elektronické příslušenství určené pro použití s kompatibilním mobilním zařízením. Zaujme uživatele, kteří hledají jiný formát doplňku k telefonu a chtějí ho sladit s každodenním nošením. Při výběru zohledněte pohodlí obrub, podporovanou aplikaci a skutečné možnosti dodávané varianty. Jejich soulad rozhoduje, které funkce vám budou užitečné doma, při práci nebo během cestování. Elektronika nemusí představovat další předmět uložený v kapse. Brýlové provedení propojuje běžný doplněk s novým způsobem používání příslušenství k telefonu.","catalog_short_t":"A classic glasses shape can also be part of your smart kit. Esaker G300 is a wearable electronic accessory designed for use with a compatible mobile device. It will appeal to users looking for a different kind of phone accessory that fits in with everyday wear. When choosing, consider the comfort of the frame, the supported app and the actual capabilities of the variant supplied. How well these fit together decides which features will be useful to you at home, at work or when travelling. Electronics need not be yet another item in your pocket. The glasses design combines an everyday accessory with a new way of using phone accessories."},{"code":"OKL-008","name_cs":"S29A – kapesní AI diktafon","name_t":"S29A – Pocket AI Voice Recorder","short_cs_text":"S29A slouží k zachycení mluveného slova, osobních poznámek a rozhovorů. Samostatné zařízení uchovává nahrávku jako podklad pro pozdější práci. Ploché tělo a vlastní ovládání doplňují přenosné provedení. Podporovaný software může převádět zvukový záznam na text a usnadnit práci s obsahem nahrávky. Dostupné jazyky, souhrny a limity zpracování závisejí na použité službě. Kvalita výsledku souvisí se srozumitelností zvuku a jazykem mluvčích. Zvuk zůstává zdrojem původního sdělení, zatímco textový výstup usnadňuje vyhledávání a další zpracování. Kompaktní rekordér odděluje pořizování záznamu od běžného ovládání telefonu. Výsledné soubory lze využít podle možností doprovodné aplikace.","short_t_text":"S29A is designed to capture speech, personal notes and conversations. As a standalone device, it stores the recording as material for later work. A flat body and its own controls complete the portable design. Supported software can convert an audio recording to text and make it easier to work with the content. The available languages, summaries and processing limits depend on the service used. The quality of the result depends on how clear the audio is and on the speakers' language. The audio remains the source of the original message, while the text output makes searching and further processing easier. The compact recorder keeps recording separate from everyday phone use. The resulting files can be used according to the capabilities of the companion app.","short_t_html":"\n                            S29A is designed to capture speech, personal notes and conversations. As a standalone device, it stores the recording as material for later work. A flat body and its own controls complete the portable design. Supported software can convert an audio recording to text and make it easier to work with the content. The available languages, summaries and processing limits depend on the service used. The quality of the result depends on how clear the audio is and on the speakers' language. The audio remains the source of the original message, while the text output makes searching and further processing easier. The compact recorder keeps recording separate from everyday phone use. The resulting files can be used according to the capabilities of the companion app.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>S29A – Pocket AI Voice Recorder</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Audio recording in a pocket format</h3><p>S29A is designed to capture speech, personal notes and conversations. As a standalone device, it stores the recording as material for later work. A flat body and its own controls complete the portable design.</p><p style=\"margin-top:16px\">The audio track preserves the original wording and the timeline of what was said. The recording can be played back later and compared with the resulting text output. The pocket-sized design keeps recording on a dedicated device, while further processing can take place in supported software.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-008-function-1.jpg\" alt=\"S29A – Pocket AI Voice Recorder – Audio recording in a pocket format\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>AI transcription</h3><p>Supported software can convert an audio recording to text and make it easier to work with the content. The available languages, summaries and processing limits depend on the service used. The quality of the result depends on how clear the audio is and on the speakers' language.</p><p style=\"margin-top:16px\">Speech-to-text creates another version of the same content that is easier to work with when reading. Speech recognition is affected by overlapping voices, background noise and pronunciation. Any automatic summary is based on the processed recording, and its scope reflects the capabilities of the service used.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-008-function-2.jpg\" alt=\"S29A – Pocket AI Voice Recorder – AI transcription\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Linking recordings with your working notes</h3><p>The audio remains the source of the original message, while the text output makes searching and further processing easier. The compact recorder keeps recording separate from everyday phone use. The resulting files can be used according to the capabilities of the companion app.</p><p style=\"margin-top:16px\">Audio and text are two complementary layers of the same material. The recording lets you go back to the voice and the exact wording, while the text makes it easier to find your way around the content. How outputs are accessed, stored and shared depends on the supported features of the app used to work with the recording.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-008-function-3.jpg\" alt=\"S29A – Pocket AI Voice Recorder – Linking recordings with your working notes\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Chytrá elektronika","Category:","Smart electronics"],["Kategorie:","Chytrá elektronika","Category:","Smart electronics"],["Model:","S29A","Model:","S29A"],["Typ produktu:","Digitální diktafon","Product type:","Digital voice recorder"],["Zaznamenávaný obsah:","Zvuk","Recorded content:","Audio"],["Provedení:","Přenosné, kapesní","Design:","Portable, pocket-sized"],["Typické použití:","Poznámky, výuka, schůzky","Typical use:","Notes, studying, meetings"],["AI funkce:","Podle aplikace a dostupné služby","AI features:","Depends on the app and the available service"]],"catalog_names":{"Kapesní AI diktafon S29A":"S29A Pocket AI Voice Recorder","S29A – kapesní AI diktafon":"S29A – Pocket AI Voice Recorder"},"catalog_short_cs":"Mějte nápady, poznámky a podklady ze schůzek pohromadě. Kapesní diktafon S29A je určen pro pořizování zvukových záznamů, ke kterým se chcete později vrátit. Malé provedení snadno zařadíte do školní nebo pracovní výbavy. Podporované AI zpracování může podle aplikace pomoci s přepisem či shrnutím, původní nahrávka ale zůstává důležitým zdrojem souvislostí. Rozsah služby, jazyky a kapacitu úložiště vždy posuzujte pro konkrétní dodávanou variantu. Ruční poznámky někdy zachytí hesla, ale ztratí souvislosti. Zvukový záznam umožňuje vrátit se k původní formulaci a doplnit chybějící kontext.","catalog_short_t":"Keep your ideas, notes and meeting materials in one place. The S29A pocket voice recorder is designed for making audio recordings you want to come back to later. Its small size makes it easy to add to your school or work kit. Depending on the app, supported AI processing can help with transcription or summaries, but the original recording remains an important source of context. Always check the scope of the service, the languages and the storage capacity for the specific variant supplied. Handwritten notes sometimes capture the key points but lose the context. An audio recording lets you return to the original wording and fill in the missing context."},{"code":"OKL-009","name_cs":"Q18 – bezdrátová překladová sluchátka","name_t":"Q18 – Wireless Translation Earphones","short_cs_text":"Sluchátka Q18 spolupracují s kompatibilním překladovým softwarem. Aplikace zpracovává řeč a zpřístupňuje podporované jazyky a režimy rozhovoru. Rozsah překladu závisí na službě, připojení a konkrétním nastavení telefonu. Vedle překladového použití slouží sluchátka pro podporovaný poslech zvuku a telefonování. Dvojice sluchátek je uložena v přenosném pouzdře. Otevřené provedení je tvarované pro nasazení kolem ucha. Tvarované lůžko udržuje obě sluchátka pohromadě a chrání je při přenášení. Pouzdro tvoří součást nabíjecího řešení. Ovládání poslechu, hovoru a překladových funkcí se řídí podporou připojeného telefonu a aplikace.","short_t_text":"Q18 earphones work with compatible translation software. The app processes speech and provides access to the supported languages and conversation modes. The scope of translation depends on the service, the connection and the specific phone settings. As well as translation, the earphones can be used for supported audio listening and phone calls. The pair of earphones is stored in a portable case. The open design is shaped to sit around the ear. Shaped cradles keep both earphones together and protect them when carried. The case is part of the charging solution. Control of listening, calls and translation features depends on what the connected phone and app support.","short_t_html":"\n                            Q18 earphones work with compatible translation software. The app processes speech and provides access to the supported languages and conversation modes. The scope of translation depends on the service, the connection and the specific phone settings. As well as translation, the earphones can be used for supported audio listening and phone calls. The pair of earphones is stored in a portable case. The open design is shaped to sit around the ear. Shaped cradles keep both earphones together and protect them when carried. The case is part of the charging solution. Control of listening, calls and translation features depends on what the connected phone and app support.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Q18 – Wireless Translation Earphones</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Translation features with an app</h3><p>Q18 earphones work with compatible translation software. The app processes speech and provides access to the supported languages and conversation modes. The scope of translation depends on the service, the connection and the specific phone settings.</p><p style=\"margin-top:16px\">The translation chain covers capturing speech, recognising it and converting it into the selected language. The earphones are the audio part of the setup, while the phone provides the app environment. The individual steps and the way the translation is delivered depend on the modes made available by the specific version of the software in use.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-009-function-1.jpg\" alt=\"Q18 – Wireless Translation Earphones – Translation features with an app\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Wireless listening and calls</h3><p>As well as translation, the earphones can be used for supported audio listening and phone calls. The pair of earphones is stored in a portable case. The open design is shaped to sit around the ear.</p><p style=\"margin-top:16px\">The audio features rely on a connection to a compatible device that streams the content being played or a phone call. The around-the-ear design holds the earphone in place and keeps its functional parts in a wearable form. The translation service complements this basic audio setup via a supported mobile app.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-009-function-2.jpg\" alt=\"Q18 – Wireless Translation Earphones – Wireless listening and calls\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Storage and charging case</h3><p>Shaped cradles keep both earphones together and protect them when carried. The case is part of the charging solution. Control of listening, calls and translation features depends on what the connected phone and app support.</p><p style=\"margin-top:16px\">Separate slots for the left and right earphones make it easy to store the whole pair as one unit. Charging contacts and matching cradles connect the earphones to the case. Small parts stay together while you are on the move, while the phone continues to provide the software environment for the available communication and translation features.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-009-function-3.jpg\" alt=\"Q18 – Wireless Translation Earphones – Storage and charging case\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Chytrá elektronika","Category:","Smart electronics"],["Kategorie:","Chytrá elektronika","Category:","Smart electronics"],["Model:","Q18","Model:","Q18"],["Typ produktu:","Bezdrátová překladová sluchátka","Product type:","Wireless translation earphones"],["Oblast použití:","Poslech, hovory a překlad přes aplikaci","Use:","Listening, calls and translation via an app"],["Spolupracující zařízení:","Kompatibilní telefon","Companion device:","Compatible phone"],["Překladové funkce:","Podle doprovodné aplikace","Translation features:","Depends on the companion app"],["Jazyková podpora:","Podle služby a režimu","Language support:","Depends on the service and mode"]],"catalog_names":{"Bezdrátová překladová sluchátka Q18":"Q18 Wireless Translation Earphones","Q18 – bezdrátová překladová sluchátka":"Q18 – Wireless Translation Earphones"},"catalog_short_cs":"Propojte každodenní poslech s možnostmi kompatibilní překladové aplikace. Bezdrátová sluchátka Q18 poslouží pro hudbu, hovory a podporované režimy práce s cizím jazykem. Při cestování mohou být užitečnou oporou běžné domluvy, zatímco telefon zajišťuje potřebné softwarové zpracování. Záleží proto na jeho kompatibilitě, připojení a podmínkách služby. Před cestou si ověřte konkrétní jazyky i způsob konverzace, který aplikace podporuje. Porozumění mluvené řeči usnadní, když máte k dispozici další zdroj významu. Q18 lze používat s podporovanou překladovou aplikací a jejími dostupnými režimy.","catalog_short_t":"Combine everyday listening with the capabilities of a compatible translation app. Q18 wireless earphones are suitable for music, calls and supported foreign-language modes. When travelling, they can be a useful aid in everyday communication, while the phone handles the necessary software processing. Its compatibility, connection and the terms of the service therefore matter. Before your trip, check the specific languages and the conversation mode supported by the app. Understanding spoken language is easier when you have an additional source of meaning. Q18 can be used with a supported translation app and its available modes."},{"code":"OKL-010","name_cs":"R99 – chytrý prsten","name_t":"R99 – Smart Ring","short_cs_text":"R99 umísťuje snímací elektroniku na vnitřní stranu prstenu. Nositelné provedení poskytuje podklady o aktivitě a dalších podporovaných ukazatelích. Získaná data se zobrazují prostřednictvím kompatibilní mobilní aplikace. Doprovodný software pracuje s dostupnými záznamy ze senzorů a vytváří osobní přehled. Podporované sledování spánku a aktivity doplňuje každodenní používání. Výstupy jsou orientační údaje spotřební nositelné elektroniky. Snímače jsou zapuštěny do vnitřní části hladké obroučky. Prsten nemá klasický velký displej a přehled dat přesouvá do telefonu. Kompaktní konstrukce zachovává podobu osobního šperku a nositelného doplňku.","short_t_text":"The R99 places its sensing electronics on the inner side of the ring. The wearable design gathers data on activity and other supported metrics. The collected data is displayed via a compatible mobile app. The companion software works with the available sensor records and builds a personal overview. Supported sleep and activity tracking complements everyday use. The outputs are indicative readings from consumer wearable electronics. The sensors are recessed into the inner part of the smooth band. The ring has no conventional large display and moves the data overview to your phone. Its compact design retains the look of a personal piece of jewellery and a wearable accessory.","short_t_html":"\n                            The R99 places its sensing electronics on the inner side of the ring. The wearable design gathers data on activity and other supported metrics. The collected data is displayed via a compatible mobile app. The companion software works with the available sensor records and builds a personal overview. Supported sleep and activity tracking complements everyday use. The outputs are indicative readings from consumer wearable electronics. The sensors are recessed into the inner part of the smooth band. The ring has no conventional large display and moves the data overview to your phone. Its compact design retains the look of a personal piece of jewellery and a wearable accessory.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>R99 – Smart Ring</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Sensors in a smart ring</h3><p>The R99 places its sensing electronics on the inner side of the ring. The wearable design gathers data on activity and other supported metrics. The collected data is displayed via a compatible mobile app.</p><p style=\"margin-top:16px\">Positioning the sensors on the inside keeps them in contact with the finger while the ring is worn. The electronics process the available signals and pass the supported data to the app. The ring thus acts as the data-collecting part of the setup, while the connected phone takes over the detailed display and further interpretation of the information gathered.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-010-function-1.jpg\" alt=\"R99 – Smart Ring – Sensors in a smart ring\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Activity and rest overview</h3><p>The companion software works with the available sensor records and builds a personal overview. Supported sleep and activity tracking complements everyday use. The outputs are indicative readings from consumer wearable electronics.</p><p style=\"margin-top:16px\">Records from individual periods let you view activity and rest over time, depending on the app's capabilities. The software turns the available data into overviews and estimated metrics. The meaning of each value depends on the processing method used and on the functions supported by the specific ring version.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-010-function-2.jpg\" alt=\"R99 – Smart Ring – Activity and rest overview\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Electronics in an enclosed band</h3><p>The sensors are recessed into the inner part of the smooth band. The ring has no conventional large display and moves the data overview to your phone. Its compact design retains the look of a personal piece of jewellery and a wearable accessory.</p><p style=\"margin-top:16px\">The outer band forms a continuous supporting structure, while the inner part houses the functional sensing elements. Separating data collection from data display keeps the wearable device small. The phone offers a larger screen for overviews, settings and reading information that would be difficult to display on the ring itself.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-010-function-3.jpg\" alt=\"R99 – Smart Ring – Electronics in an enclosed band\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Chytrá elektronika","Category:","Smart electronics"],["Kategorie:","Chytrá elektronika","Category:","Smart electronics"],["Model:","R99","Model:","R99"],["Typ produktu:","Chytrý prsten","Product type:","Smart ring"],["Provedení:","Nositelné příslušenství na prst","Design:","Wearable finger accessory"],["Volba varianty:","Podle velikosti prstenu","Variant selection:","By ring size"],["Softwarové funkce:","Podle kompatibilní aplikace","Software features:","Depending on the compatible app"],["Určení:","Spotřební nositelná elektronika","Intended use:","Consumer wearable electronics"]],"catalog_names":{"Chytrý prsten R99":"R99 Smart Ring","R99 – chytrý prsten":"R99 – Smart Ring"},"catalog_short_cs":"Objevte nositelnou elektroniku v nenápadném formátu prstenu. R99 je alternativou pro uživatele, kteří dávají přednost malému doplňku před běžnými chytrými hodinkami. Při výběru záleží na správné velikosti, pohodlném usazení a podpoře doprovodné aplikace. Konkrétní funkce a zobrazované údaje se odvíjejí od dodávané varianty, nikoli pouze od vzhledu. Zajímavá volba pro zájemce o nové formáty každodenní elektroniky, kteří chtějí hlavní přehled sledovat v kompatibilním telefonu. Prsten poskytuje odlišný způsob nošení než náramek s displejem. Může vyhovovat uživatelům, kteří chtějí nenápadnější doplněk a nevadí jim pracovat s přehledem v telefonu.","catalog_short_t":"Discover wearable electronics in a discreet ring format. The R99 is an alternative for users who prefer a small accessory to a conventional smartwatch. When choosing, the right size, a comfortable fit and support from the companion app all matter. The specific functions and displayed data depend on the variant supplied, not just on its appearance. An interesting choice for anyone curious about new formats of everyday electronics who wants to follow the main overview on a compatible phone. The ring offers a different way of wearing than a wristband with a display. It may suit users who want a more discreet accessory and don't mind working with the overview on their phone."},{"code":"OKL-011","name_cs":"Digitální USB-C tester napájení","name_t":"Digital USB-C Power Tester","short_cs_text":"USB-C tester zobrazuje elektrické veličiny přímo v napájecí trase. Barevná obrazovka sdružuje aktuální napětí, proud a vypočtený výkon. Přístroj tvoří průchozí prvek mezi kompatibilním zdrojem, kabelem a napájeným zařízením. Tester pomáhá sledovat chování USB-C napájení a podporované nabíjecí protokoly. Údaje jsou dostupné bez samostatného počítačového monitoru. Konkrétní režim nabíjení vzniká dohodou zdroje, kabelu a připojeného zařízení. Průchozí konektory dovolují sledovat odběr při běžném napájení elektroniky. Změna zátěže se projeví na hodnotách obrazovky. Tester tak poskytuje přehled pro porovnání kompatibilních kabelů, nabíječek a USB-C příslušenství.","short_t_text":"The USB-C tester displays electrical values directly within the power path. Its colour screen brings together the present voltage, current and calculated power. The device sits inline between a compatible power source, cable and the powered device. The tester helps you monitor USB-C power behaviour and supported charging protocols. The readings are available without a separate computer monitor. The actual charging mode results from negotiation between the power source, cable and connected device. Pass-through connectors let you monitor current draw while electronics are powered as usual. Any change in load is reflected in the values on screen. The tester thus provides an overview for comparing compatible cables, chargers and USB-C accessories.","short_t_html":"\n                            The USB-C tester displays electrical values directly within the power path. Its colour screen brings together the present voltage, current and calculated power. The device sits inline between a compatible power source, cable and the powered device. The tester helps you monitor USB-C power behaviour and supported charging protocols. The readings are available without a separate computer monitor. The actual charging mode results from negotiation between the power source, cable and connected device. Pass-through connectors let you monitor current draw while electronics are powered as usual. Any change in load is reflected in the values on screen. The tester thus provides an overview for comparing compatible cables, chargers and USB-C accessories.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Digital USB-C Power Tester</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Voltage, current and power on the display</h3><p>The USB-C tester displays electrical values directly within the power path. Its colour screen brings together the present voltage, current and calculated power. The device sits inline between a compatible power source, cable and the powered device.</p><p style=\"margin-top:16px\">Showing several values at once links the instantaneous current draw to the source voltage. Power expresses the relationship between them and changes with the operation of the connected load. The display therefore shows the state of the specific connection at any given moment, including changes during charging or while the device is running.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-011-function-1.jpg\" alt=\"Digital USB-C Power Tester – Voltage, current and power on the display\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Overview of supported charging</h3><p>The tester helps you monitor USB-C power behaviour and supported charging protocols. The readings are available without a separate computer monitor. The actual charging mode results from negotiation between the power source, cable and connected device.</p><p style=\"margin-top:16px\">The available power mode depends on the capabilities of every part of the connection. The USB-C connector alone determines neither the resulting voltage nor the power drawn. The displayed values let you distinguish the current operating state from the maximum power stated on the power source, which the connected electronics may not use at every moment.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-011-function-2.jpg\" alt=\"Digital USB-C Power Tester – Overview of supported charging\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Measuring in a real power path</h3><p>Pass-through connectors let you monitor current draw while electronics are powered as usual. Any change in load is reflected in the values on screen. The tester thus provides an overview for comparing compatible cables, chargers and USB-C accessories.</p><p style=\"margin-top:16px\">Placing the tester in the power path ties the measurement to the real-world operation of the connected device. The screen makes the readings available without disconnecting the setup to take a separate reading. Differences between individual connections can be assessed from the displayed values within the range supported by the specific version of the meter.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-011-function-3.jpg\" alt=\"Digital USB-C Power Tester – Measuring in a real power path\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Měřicí technika a nářadí","Category:","Measuring instruments and tools"],["Kategorie:","Měřicí technika a nářadí","Category:","Measuring instruments and tools"],["Připojení:","USB C","Connection:","USB C"],["Typ produktu:","Digitální tester napájení","Product type:","Digital power tester"],["Rozhraní:","USB-C","Interface:","USB-C"],["Základní účel:","Kontrola napětí a proudu","Main purpose:","Checking voltage and current"],["Zobrazení:","Digitální","Display:","Digital"],["Místo zapojení:","Kompatibilní napájecí cesta","Connection point:","Compatible power path"],["Použití:","Orientační kontrola nabíjecí sestavy","Use:","Indicative check of a charging setup"]],"catalog_names":{"Digitální USB C tester napájení":"Digital USB C Power Tester","Digitální USB-C tester napájení":"Digital USB-C Power Tester"},"catalog_short_cs":"Zjistěte, jak se při nabíjení chová konkrétní sestava zdroje, kabelu a zařízení. Digitální USB-C tester slouží ke kontrole podporovaných elektrických veličin na kompatibilním propojení a pomáhá s orientačním porovnáváním nabíjecí výbavy. Využijete ho doma, při základní diagnostice i na pracovním stole. Místo odhadu podle samotné nabíjecí ikony získáte další informace o přenosu energie. Před zapojením vždy porovnejte napětí, proud a protokoly sestavy s limity konkrétního testeru. Telefon může zobrazovat nabíjení, aniž by tím popisoval chování celé sestavy. Tester vložený do podporované napájecí cesty umožňuje sledovat dostupné veličiny a porovnávat zdroje nebo kabely.","catalog_short_t":"Find out how a specific combination of power source, cable and device behaves during charging. The digital USB-C tester is used to check supported electrical values on a compatible connection and helps with indicative comparisons of charging equipment. Use it at home, for basic diagnostics or on your workbench. Instead of guessing from the charging icon alone, you get more information about power transfer. Before connecting, always compare the voltage, current and protocols of your setup with the limits of the specific tester. A phone may show that it is charging without describing how the whole setup behaves. Placed in a supported power path, the tester lets you monitor the available values and compare power sources or cables."},{"code":"OKL-012","name_cs":"Digitální kapesní váha s rozlišením 0,01 g","name_t":"Digital Pocket Scale with 0.01 g Resolution","short_cs_text":"Digitální váha zobrazuje hmotnost v krocích po 0,01 g. Jemné rozlišení je určené pro práci s drobnými předměty. Hodnota rozlišení popisuje krok displeje, nikoli samostatnou záruku přesnosti každého měření. Kovová vážicí plocha doplňuje číselný displej a fyzická tlačítka. Funkce tárování odděluje hmotnost nádoby od vloženého obsahu. Výsledek je dostupný přímo na zařízení bez propojení s telefonem. Nízké tělo a průhledný kryt chrání vážicí plochu při uložení. Váha vytváří samostatné přenosné měřidlo pro drobné předměty a součástky. Kompaktní konstrukce spojuje plochu, displej a ovládání do jednoho celku.","short_t_text":"The digital scale displays weight in 0.01 g increments. The fine resolution is designed for working with small items. The resolution value describes the display step, not a separate guarantee of the accuracy of every measurement. A metal weighing platform complements the numerical display and physical buttons. The tare function separates the weight of a container from its contents. The result is available directly on the device without connecting to a phone. The low-profile body and transparent cover protect the weighing platform during storage. The scale is a self-contained portable instrument for small items and components. Its compact design combines the platform, display and controls in a single unit.","short_t_html":"\n                            The digital scale displays weight in 0.01 g increments. The fine resolution is designed for working with small items. The resolution value describes the display step, not a separate guarantee of the accuracy of every measurement. A metal weighing platform complements the numerical display and physical buttons. The tare function separates the weight of a container from its contents. The result is available directly on the device without connecting to a phone. The low-profile body and transparent cover protect the weighing platform during storage. The scale is a self-contained portable instrument for small items and components. Its compact design combines the platform, display and controls in a single unit.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Digital Pocket Scale with 0.01 g Resolution</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>0.01 gram resolution</h3><p>The digital scale displays weight in 0.01 g increments. The fine resolution is designed for working with small items. The resolution value describes the display step, not a separate guarantee of the accuracy of every measurement.</p><p style=\"margin-top:16px\">The numerical reading distinguishes small increments in weight and lets you follow the change as contents are gradually added. The fine display step gives a more detailed reading than scales showing whole grams. The actual result, however, depends on the scale's measuring system and the conditions of the specific weighing, not merely on the number of decimal places.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-012-function-1.jpg\" alt=\"Digital Pocket Scale with 0.01 g Resolution – 0.01 gram resolution\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Weighing platform and digital controls</h3><p>A metal weighing platform complements the numerical display and physical buttons. The tare function separates the weight of a container from its contents. The result is available directly on the device without connecting to a phone.</p><p style=\"margin-top:16px\">Taring sets the starting reading with the container on the platform, so the next reading corresponds to the added contents. The display and buttons are separate from the weighing area and remain accessible while an item is on the scale. The direct digital readout reduces the need to manually calculate the difference between the weight of the container and the total.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-012-function-2.jpg\" alt=\"Digital Pocket Scale with 0.01 g Resolution – Weighing platform and digital controls\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Pocket design with a cover</h3><p>The low-profile body and transparent cover protect the weighing platform during storage. The scale is a self-contained portable instrument for small items and components. Its compact design combines the platform, display and controls in a single unit.</p><p style=\"margin-top:16px\">The cover shields the working surface when the scale is carried and helps keep it separate from other stored items. Once opened, both the weighing area and the readout panel are accessible. The self-contained design combines the measuring mechanism, power supply and display in one device that can be stored without any additional display unit.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-012-function-3.jpg\" alt=\"Digital Pocket Scale with 0.01 g Resolution – Pocket design with a cover\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Měřicí technika a nářadí","Category:","Measuring instruments and tools"],["Kategorie:","Měřicí technika a nářadí","Category:","Measuring instruments and tools"],["Rozlišení:","0,01 g","Resolution:","0,01 g"],["Typ produktu:","Digitální kapesní váha","Product type:","Digital pocket scale"],["Rozlišení zobrazení:","0,01 g","Display resolution:","0,01 g"],["Měřená veličina:","Hmotnost","Measured quantity:","Weight"],["Zobrazení:","Digitální","Display:","Digital"],["Provedení:","Přenosné","Design:","Portable"],["Určení:","Vážení drobných předmětů","Intended use:","Weighing small items"]],"catalog_names":{"Digitální kapesní váha 0,01 g":"Digital Pocket Scale 0.01 g","Digitální kapesní váha s rozlišením 0,01 g":"Digital Pocket Scale with 0.01 g Resolution"},"catalog_short_cs":"Když vážíte drobné předměty, i malý rozdíl může být důležitý. Kapesní digitální váha s rozlišením 0,01 g se hodí pro jemné součástky, sběratelské materiály a další úlohy, při kterých potřebujete přehledný číselný odečet. Kompaktní provedení snadno uložíte do pracovní výbavy a připravíte tam, kde právě pracujete. Pro použitelný výsledek ji položte na rovnou stabilní plochu a dodržujte limity konkrétní varianty. Rozlišení displeje přitom rozlišujte od skutečné přesnosti měření. Digitální odečet pomáhá porovnávat lehké předměty bez odhadování polohy mechanické stupnice. Krok 0,01 g umožňuje jemné zobrazení výsledku, sám ale nevyjadřuje maximální chybu měření.","catalog_short_t":"When you weigh small items, even a tiny difference can matter. A pocket digital scale with 0.01 g resolution is ideal for delicate components, collectors' materials and other tasks where you need a clear numerical reading. Its compact design is easy to store in your work kit and set up wherever you happen to be working. For a usable result, place it on a flat, stable surface and observe the limits of the specific variant. Bear in mind that display resolution is not the same as actual measuring accuracy. The digital reading helps you compare light items without estimating a position on a mechanical scale. The 0.01 g step allows a fine display of the result, but on its own it does not express the maximum measurement error."},{"code":"OKL-013","name_cs":"Laserový dálkoměr pro digitální měření","name_t":"Laser Distance Meter for Digital Measuring","short_cs_text":"Dálkoměr určuje vzdálenost pomocí laserového měřicího systému. Číselný výsledek zobrazuje přímo na obrazovce přístroje. Samostatné měření usnadňuje získání délkového údaje bez rozvíjení měřicí pásky přes celý prostor. Čelní panel sdružuje obrazovku a fyzická tlačítka pro dostupné režimy. Jednotlivé hodnoty jsou přístupné přímo na přístroji. Konstrukce měřidla je přizpůsobena ručnímu používání a rychlému odečtení výsledku. Laserová optika, elektronika a napájení jsou umístěny v jednom přenosném těle. Zadní část zahrnuje prostor pro baterie. Přístroj slouží pro digitální měření vzdáleností v rozsahu konkrétní dodané varianty.","short_t_text":"The distance meter determines distance using a laser measuring system. It shows the numerical result directly on the device's screen. Stand-alone measuring makes it easy to obtain a length reading without unrolling a tape measure across the entire space. The front panel brings together the screen and physical buttons for the available modes. Individual values can be accessed directly on the device. The meter is designed for handheld use and quick reading of the result. The laser optics, electronics and power supply are housed in a single portable body. The rear section includes the battery compartment. The device is used for digital distance measurement within the range of the specific variant supplied.","short_t_html":"\n                            The distance meter determines distance using a laser measuring system. It shows the numerical result directly on the device's screen. Stand-alone measuring makes it easy to obtain a length reading without unrolling a tape measure across the entire space. The front panel brings together the screen and physical buttons for the available modes. Individual values can be accessed directly on the device. The meter is designed for handheld use and quick reading of the result. The laser optics, electronics and power supply are housed in a single portable body. The rear section includes the battery compartment. The device is used for digital distance measurement within the range of the specific variant supplied.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Laser Distance Meter for Digital Measuring</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Laser measuring principle</h3><p>The distance meter determines distance using a laser measuring system. It shows the numerical result directly on the device's screen. Stand-alone measuring makes it easy to obtain a length reading without unrolling a tape measure across the entire space.</p><p style=\"margin-top:16px\">Optical measuring combines aiming at the target surface with electronic evaluation of the distance. The output is a numerical value that can be read immediately. The result relates to the measured path and to the reference point set on the device; the usability of a given measurement is also affected by the nature of the surface and the ambient light.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-013-function-1.jpg\" alt=\"Laser Distance Meter for Digital Measuring – Laser measuring principle\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Display and button controls</h3><p>The front panel brings together the screen and physical buttons for the available modes. Individual values can be accessed directly on the device. The meter is designed for handheld use and quick reading of the result.</p><p style=\"margin-top:16px\">The button panel separates triggering a measurement from reading the resulting value. The selected mode determines how the available data is handled, according to the functions of the specific variant. The built-in screen keeps the result right on the meter, so no connected phone or computer interface is needed for a basic reading.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-013-function-2.jpg\" alt=\"Laser Distance Meter for Digital Measuring – Display and button controls\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Compact meter body</h3><p>The laser optics, electronics and power supply are housed in a single portable body. The rear section includes the battery compartment. The device is used for digital distance measurement within the range of the specific variant supplied.</p><p style=\"margin-top:16px\">The portable design keeps the optical and electronic parts in a shared housing. Power from the battery compartment allows the device to operate independently. The measuring range and available modes are properties of the given model, while the compact body makes the whole unit easy to handle when taking digital distance readings.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-013-function-3.jpg\" alt=\"Laser Distance Meter for Digital Measuring – Compact meter body\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Měřicí technika a nářadí","Category:","Measuring instruments and tools"],["Kategorie:","Měřicí technika a nářadí","Category:","Measuring instruments and tools"],["Typ produktu:","Laserový digitální dálkoměr","Product type:","Laser digital distance meter"],["Měřená veličina:","Vzdálenost","Measured quantity:","Distance"],["Princip měření:","Laserový","Measuring principle:","Laser"],["Zobrazení:","Digitální","Display:","Digital"],["Typické použití:","Plánování interiéru a dílenské měření","Typical use:","Interior planning and workshop measuring"],["Provedení:","Ruční přenosné","Design:","Handheld, portable"]],"catalog_names":{"Laserový digitální dálkoměr":"Laser Digital Distance Meter","Laserový dálkoměr pro digitální měření":"Laser Distance Meter for Digital Measuring"},"catalog_short_cs":"Změřte vzdálenost bez zdlouhavého natahování pásma přes celou místnost. Laserový digitální dálkoměr se hodí při plánování interiéru, rozmísťování nábytku a běžných měřicích úlohách v domácnosti nebo dílně. Číselný odečet usnadňuje zapisování rozměrů a postupnou kontrolu více míst. Přístroj umístíte podle zvolené referenční hrany a zaměříte vhodný cílový povrch. Pro přesný pracovní postup zohledněte měřicí rozsah, podmínky okolí a funkce konkrétní varianty. Při přípravě nového uspořádání potřebujete rychle získat několik srovnatelných rozměrů. Dálkoměr pomůže změřit podporovanou vzdálenost a přečíst ji digitálně přímo na zařízení.","catalog_short_t":"Measure distances without laboriously stretching a tape measure across the whole room. The laser digital distance meter is ideal for interior planning, arranging furniture and everyday measuring tasks at home or in the workshop. The numerical reading makes it easier to note down dimensions and check several spots one after another. Position the device against your chosen reference edge and aim at a suitable target surface. For an accurate workflow, take into account the measuring range, ambient conditions and the functions of the specific variant. When preparing a new layout, you need to get several comparable dimensions quickly. The distance meter helps you measure a supported distance and read it digitally right on the device."},{"code":"OKL-014","name_cs":"Digitální tloušťkoměr pro kontrolu materiálů","name_t":"Digital Thickness Gauge for Material Inspection","short_cs_text":"Tloušťkoměr měří vzdálenost mezi protilehlými dotykovými plochami. Vložený materiál je sevřen měřicími kontakty a výsledek se zobrazuje digitálně. Konstrukce se hodí pro dostupná místa na plochých vzorcích, nikoli pro bezkontaktní měření povlaku. Samostatný číselný displej umožňuje číst výsledek přímo z měřicí hlavy. Tlačítka doplňují ovládání podporovaných funkcí měřidla. Mechanický rám drží měřicí kontakty v pevně dané vzájemné poloze. Páčka oddaluje pohyblivý kontakt pro vložení vzorku. Otevřený tvar rámu poskytuje přístup k okraji měřeného materiálu. Měřicí hlava a kontaktní části tvoří jeden ruční přístroj pro opakovaný odečet tloušťky.","short_t_text":"The thickness gauge measures the distance between opposing contact surfaces. The inserted material is clamped between the measuring contacts and the result is displayed digitally. The design suits accessible spots on flat samples; it is not intended for non-contact coating measurement. A dedicated numerical display lets you read the result directly from the measuring head. Buttons provide control of the gauge's supported functions. The mechanical frame holds the measuring contacts in a fixed relative position. The lever retracts the movable contact so you can insert a sample. The open shape of the frame provides access to the edge of the material being measured. The measuring head and contact parts form a single handheld instrument for repeated thickness readings.","short_t_html":"\n                            The thickness gauge measures the distance between opposing contact surfaces. The inserted material is clamped between the measuring contacts and the result is displayed digitally. The design suits accessible spots on flat samples; it is not intended for non-contact coating measurement. A dedicated numerical display lets you read the result directly from the measuring head. Buttons provide control of the gauge's supported functions. The mechanical frame holds the measuring contacts in a fixed relative position. The lever retracts the movable contact so you can insert a sample. The open shape of the frame provides access to the edge of the material being measured. The measuring head and contact parts form a single handheld instrument for repeated thickness readings.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Digital Thickness Gauge for Material Inspection</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Contact thickness measurement</h3><p>The thickness gauge measures the distance between opposing contact surfaces. The inserted material is clamped between the measuring contacts and the result is displayed digitally. The design suits accessible spots on flat samples; it is not intended for non-contact coating measurement.</p><p style=\"margin-top:16px\">The resulting reading describes the total thickness of the sample inserted between the contacts. The measuring principle requires access to both opposite sides of the material. The open part of the frame determines how far from the edge the contacts can be applied, and the mechanical arrangement converts their relative position into a value for digital readout.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-014-function-1.jpg\" alt=\"Digital Thickness Gauge for Material Inspection – Contact thickness measurement\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Digital value readout</h3><p>A dedicated numerical display lets you read the result directly from the measuring head. Buttons provide control of the gauge's supported functions. The mechanical frame holds the measuring contacts in a fixed relative position.</p><p style=\"margin-top:16px\">The screen shows the reading right at the point of measurement and removes the need to read fine graduations on a mechanical scale. The fixed part and the movable contact form the basis of the measuring arrangement. The electronic head displays the distance between them as a readable value whose resolution and range depend on the specific model.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-014-function-2.jpg\" alt=\"Digital Thickness Gauge for Material Inspection – Digital value readout\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Frame with operating lever</h3><p>The lever retracts the movable contact so you can insert a sample. The open shape of the frame provides access to the edge of the material being measured. The measuring head and contact parts form a single handheld instrument for repeated thickness readings.</p><p style=\"margin-top:16px\">The operating lever gives direct control over opening the measuring gap. Once a sample is inserted, the contacts rest against its opposite surfaces, providing the basis for a reading. The frame design maintains the alignment of the measuring parts, which is particularly important when comparing the thickness of several small samples.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-014-function-3.jpg\" alt=\"Digital Thickness Gauge for Material Inspection – Frame with operating lever\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Měřicí technika a nářadí","Category:","Measuring instruments and tools"],["Kategorie:","Měřicí technika a nářadí","Category:","Measuring instruments and tools"],["Typ produktu:","Digitální tloušťkoměr","Product type:","Digital thickness gauge"],["Měřená veličina:","Tloušťka","Measured quantity:","Thickness"],["Zobrazení:","Digitální","Display:","Digital"],["Typické použití:","Kontrola vhodných materiálů a dílů","Typical use:","Inspection of suitable materials and parts"],["Provedení:","Ruční měřidlo","Design:","Handheld gauge"],["Volba měřidla:","Podle materiálu a měřicího principu","Gauge selection:","According to material and measuring principle"]],"catalog_names":{"Digitální tloušťkoměr pro měření materiálů":"Digital Thickness Gauge for Measuring Materials","Digitální tloušťkoměr pro kontrolu materiálů":"Digital Thickness Gauge for Material Inspection"},"catalog_short_cs":"Získejte přehledný číselný odečet při kontrole tloušťky vhodných materiálů a drobných dílů. Digitální tloušťkoměr je praktickou součástí technické výbavy pro porovnávání vzorků, kontrolu rozměrů a opakované měřicí úlohy. Místo odhadu na stupnici pracujete s digitálně zobrazenou hodnotou. Správný výsledek závisí na vhodnosti měřidla pro daný materiál, čistotě měřicích ploch a správném usazení vzorku. Před prací ověřte rozsah a konstrukci konkrétní varianty. Když porovnáváte několik vzorků, číselné zobrazení usnadní zápis a hledání rozdílů. Tloušťkoměr může tvořit součást stálého pracovního postupu, při kterém měříte vždy na stejném místě a za stejných podmínek.","catalog_short_t":"Get a clear numerical reading when checking the thickness of suitable materials and small parts. The digital thickness gauge is a practical addition to your technical equipment for comparing samples, checking dimensions and repeated measuring tasks. Instead of estimating on a scale, you work with a digitally displayed value. A correct result depends on the gauge being suitable for the material, clean measuring surfaces and proper seating of the sample. Before starting, check the range and design of the specific variant. When comparing several samples, the numerical display makes it easier to record values and spot differences. The thickness gauge can become part of a consistent workflow in which you always measure at the same point and under the same conditions."},{"code":"OKL-015","name_cs":"USB digitální mikroskop pro detailní pozorování","name_t":"USB Digital Microscope for Detailed Observation","short_cs_text":"Mikroskop převádí obraz z blízkosti objektivu do digitální podoby. Zvětšené zobrazení slouží k pozorování povrchů, součástek a jemných struktur. Výsledný obraz lze sledovat na kompatibilním připojeném zařízení. Světelné prvky v okolí objektivu osvětlují pozorované místo z malé vzdálenosti. Zaostřovací ovladač přizpůsobuje obraz poloze vzorku. Optika a snímací elektronika jsou soustředěny do kompaktní válcové části. Součástí provedení je polohovatelný držák se základnou. Podpírá mikroskop při detailním pozorování a ponechává prostor pod objektivem. USB propojení slouží pro podporované připojení k zařízení a napájení podle konkrétní konfigurace.","short_t_text":"The microscope converts the image from just in front of the lens into digital form. The magnified view is used to observe surfaces, components and fine structures. The resulting image can be viewed on a compatible connected device. Light sources around the lens illuminate the observed area from close range. The focus control adjusts the image to the position of the sample. The optics and imaging electronics are housed in a compact cylindrical body. The design includes an adjustable holder with a base. It supports the microscope during detailed observation and leaves space beneath the lens. The USB connection provides supported connectivity to a device and power, depending on the specific configuration.","short_t_html":"\n                            The microscope converts the image from just in front of the lens into digital form. The magnified view is used to observe surfaces, components and fine structures. The resulting image can be viewed on a compatible connected device. Light sources around the lens illuminate the observed area from close range. The focus control adjusts the image to the position of the sample. The optics and imaging electronics are housed in a compact cylindrical body. The design includes an adjustable holder with a base. It supports the microscope during detailed observation and leaves space beneath the lens. The USB connection provides supported connectivity to a device and power, depending on the specific configuration.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>USB Digital Microscope for Detailed Observation</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Digital image of fine details</h3><p>The microscope converts the image from just in front of the lens into digital form. The magnified view is used to observe surfaces, components and fine structures. The resulting image can be viewed on a compatible connected device.</p><p style=\"margin-top:16px\">The imaging section captures a small area in front of the lens and converts it into an image available in supported software. The view combines optical magnification with the capabilities of the connected screen. The level of visible detail is affected by focus, the distance to the sample and the resolution of the entire imaging system, not just by the size of the image on the display.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-015-function-1.jpg\" alt=\"USB Digital Microscope for Detailed Observation – Digital image of fine details\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Lighting around the lens</h3><p>Light sources around the lens illuminate the observed area from close range. The focus control adjusts the image to the position of the sample. The optics and imaging electronics are housed in a compact cylindrical body.</p><p style=\"margin-top:16px\">Light positioned close to the optical axis helps reveal fine surface texture within the field of view. The focusing section adjusts sharpness for the current position of the observed object. Changing the distance and lighting affects how details appear, as well as the reflections that show up in the digital image when viewing shiny components.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-015-function-2.jpg\" alt=\"USB Digital Microscope for Detailed Observation – Lighting around the lens\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Stand for stable observation</h3><p>The design includes an adjustable holder with a base. It supports the microscope during detailed observation and leaves space beneath the lens. The USB connection provides supported connectivity to a device and power, depending on the specific configuration.</p><p style=\"margin-top:16px\">The holder limits movement of the imaging section relative to the observed object and lets you maintain the chosen view. The base supports the whole assembly, while the working area remains beneath the lens. The cable connection transfers the image to supported software, which provides functions appropriate to the specific system and microscope version.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-015-function-3.jpg\" alt=\"USB Digital Microscope for Detailed Observation – Stand for stable observation\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Měřicí technika a nářadí","Category:","Measuring instruments and tools"],["Kategorie:","Měřicí technika a nářadí","Category:","Measuring instruments and tools"],["Typ produktu:","Digitální mikroskop","Product type:","Digital microscope"],["Zobrazení:","Digitální obraz","Display:","Digital image"],["Rozhraní:","USB podle varianty","Interface:","USB, depending on variant"],["Určení:","Pozorování drobných objektů a povrchů","Intended use:","Observing small objects and surfaces"],["Typické objekty:","Elektronika, mince a vzorky materiálů","Typical objects:","Electronics, coins and material samples"],["Způsob práce:","Zaostření na stabilně umístěný objekt","Method of use:","Focusing on a stably positioned object"]],"catalog_names":{"USB digitální mikroskop s displejem":"USB Digital Microscope with Display","USB digitální mikroskop pro detailní pozorování":"USB Digital Microscope for Detailed Observation"},"catalog_short_cs":"Podívejte se blíž na elektronické součástky, strukturu povrchů, mince a další drobné objekty. Digitální mikroskop pomáhá zobrazit detaily, které při běžném pohledu snadno přehlédnete. Využijete ho při domácím poznávání, kontrole předmětů i drobné servisní práci. O výsledku rozhoduje správné zaostření, stabilní uchycení a vhodné osvětlení. Způsob zobrazení na displeji nebo připojeném zařízení se řídí konkrétní variantou a kompatibilním softwarem. Při prohlížení malého objektu nejprve vyberte místo, které chcete sledovat, a nastavte takovou vzdálenost, aby se dalo pohodlně zaostřit. Digitální zobrazení umožní pozorovat strukturu a porovnat jednotlivé části předmětu.","catalog_short_t":"Take a closer look at electronic components, surface textures, coins and other small objects. A digital microscope helps reveal details that are easy to miss with the naked eye. Use it for exploring at home, inspecting items or small repair jobs. The result depends on correct focusing, stable mounting and suitable lighting. How the image is displayed on the screen or a connected device depends on the specific variant and compatible software. When examining a small object, first choose the spot you want to observe and set a distance that allows comfortable focusing. The digital view lets you observe the structure and compare individual parts of the object."},{"code":"OKL-016","name_cs":"Elektrický precizní šroubovák – servisní sada","name_t":"Electric Precision Screwdriver – Service Kit","short_cs_text":"Šroubovák používá kompaktní motorové provedení v úzkém těle. Dvojice tlačítek ovládá směr otáčení při šroubování a povolování. Nástroj je určen pro drobné šroubové spoje v elektronice a podobných mechanismech. Sada obsahuje výměnné precizní bity uložené v organizéru. Jejich výměna přizpůsobuje pracovní konec jednotlivým typům šroubů. Válcové tělo nabízí přímý úchop blízko osy šroubování. Nástroj a drobné součásti mají vlastní místa v přenosném pouzdře. Uspořádání drží příslušenství pohromadě při práci i uložení. Nabíjecí provedení omezuje potřebu vést při samotném šroubování napájecí kabel k ruce.","short_t_text":"The screwdriver uses a compact motor design in a slim body. A pair of buttons controls the direction of rotation for driving and loosening screws. The tool is designed for small screw fastenings in electronics and similar mechanisms. The kit contains interchangeable precision bits stored in an organiser. Swapping them adapts the working end to different types of screws. The cylindrical body offers a straight grip close to the screwing axis. The tool and small parts each have their own place in the portable case. This arrangement keeps the accessories together both during work and in storage. The rechargeable design reduces the need for a power cable running to your hand while you are actually driving screws.","short_t_html":"\n                            The screwdriver uses a compact motor design in a slim body. A pair of buttons controls the direction of rotation for driving and loosening screws. The tool is designed for small screw fastenings in electronics and similar mechanisms. The kit contains interchangeable precision bits stored in an organiser. Swapping them adapts the working end to different types of screws. The cylindrical body offers a straight grip close to the screwing axis. The tool and small parts each have their own place in the portable case. This arrangement keeps the accessories together both during work and in storage. The rechargeable design reduces the need for a power cable running to your hand while you are actually driving screws.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Electric Precision Screwdriver – Service Kit</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Electric drive in a precision pen</h3><p>The screwdriver uses a compact motor design in a slim body. A pair of buttons controls the direction of rotation for driving and loosening screws. The tool is designed for small screw fastenings in electronics and similar mechanisms.</p><p style=\"margin-top:16px\">The motor transfers rotation to the fitted bit and provides repeated movement without constantly turning the whole handle. Switching direction distinguishes between tightening and loosening a fastening. The tool's slim profile allows one-handed operation and brings your grip closer to the work point in small electronic assemblies.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-016-function-1.jpg\" alt=\"Electric Precision Screwdriver – Service Kit – Electric drive in a precision pen\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Interchangeable bits for small fastenings</h3><p>The kit contains interchangeable precision bits stored in an organiser. Swapping them adapts the working end to different types of screws. The cylindrical body offers a straight grip close to the screwing axis.</p><p style=\"margin-top:16px\">The bit's working profile forms the link between the drive and the screw head. The interchangeable design lets you keep the same handle and change only the tip of the tool. The organiser keeps each bit in its own slot, so their shapes remain easy to identify even when working with a larger number of small fastenings.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-016-function-2.jpg\" alt=\"Electric Precision Screwdriver – Service Kit – Interchangeable bits for small fastenings\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Case with organised accessories</h3><p>The tool and small parts each have their own place in the portable case. This arrangement keeps the accessories together both during work and in storage. The rechargeable design reduces the need for a power cable running to your hand while you are actually driving screws.</p><p style=\"margin-top:16px\">Separate slots in the case help keep the bits apart from the screwdriver body and limit their movement when carried. The entire kit stays stored together as one unit. Charging the built-in drive is separate from the actual screwing, which leaves the handle free of a connected cable while you work.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-016-function-3.jpg\" alt=\"Electric Precision Screwdriver – Service Kit – Case with organised accessories\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Měřicí technika a nářadí","Category:","Measuring instruments and tools"],["Kategorie:","Měřicí technika a nářadí","Category:","Measuring instruments and tools"],["Typ produktu:","Elektrický precizní šroubovák","Product type:","Electric precision screwdriver"],["Provedení:","Servisní sada","Design:","Service kit"],["Pohon:","Elektrický","Drive:","Electric"],["Určení:","Drobné šroubové spoje","Intended use:","Small screw fastenings"],["Typické použití:","Servis a sestavování elektroniky","Typical use:","Electronics servicing and assembly"],["Pracovní nástroj:","Kompatibilní výměnný bit","Working tool:","Compatible interchangeable bit"]],"catalog_names":{"Elektrický precizní šroubovák servisní sada":"Electric Precision Screwdriver Service Kit","Elektrický precizní šroubovák – servisní sada":"Electric Precision Screwdriver – Service Kit"},"catalog_short_cs":"Zpříjemněte si práci s drobnými šrouby při sestavování a opravách elektroniky. Elektrický precizní šroubovák pomáhá při opakovaném šroubování a servisní sada poskytuje základ pro práci s podporovanými spoji. Uplatní se na pracovním stole hobby opraváře i při rozebírání vlastních zařízení. Správně zvolený bit, malý přítlak a kontrolované dotažení jsou důležitější než rychlost práce. Před použitím ověřte velikost a typ šroubu i možnosti konkrétního nástroje. Při rozebírání krytu nebo montáži menších částí se stejný pohyb opakuje mnohokrát. Elektrický pohon může tuto část práce usnadnit a pomoci zachovat plynulý postup.","catalog_short_t":"Make working with tiny screws more pleasant when assembling and repairing electronics. The electric precision screwdriver helps with repetitive screwing, and the service kit provides a basis for working with supported fastenings. It is at home on a hobby repairer's workbench as well as when taking apart your own devices. The right bit, light pressure and controlled tightening matter more than working speed. Before use, check the size and type of screw as well as the capabilities of the specific tool. When dismantling a cover or assembling smaller parts, the same movement is repeated many times. The electric drive can make this part of the job easier and help you keep a smooth workflow."},{"code":"OKL-017","name_cs":"Kompaktní USB-C páječka pro elektroniku","name_t":"Compact USB-C Soldering Iron for Electronics","short_cs_text":"Úzké tělo soustředí topnou část, ovládání a napájecí elektroniku do přenosného nástroje. Hrot přivádí teplo přímo na pájený spoj. USB-C připojení doplňuje napájecí řešení této kompaktní páječky. Tlačítka a indikační prvky jsou umístěny na horní straně pera. Podporované nastavení je dostupné bez samostatné velké stanice. Tvar rukojeti umožňuje vést hrot při práci s drobnými elektronickými spoji. Úzký pracovní hrot je doplněn odkládacím příslušenstvím podle vyobrazeného provedení. Přenosný formát sdružuje potřebné části do malé sestavy. Nástroj je zaměřen na drobné pájení elektroniky a jemné pracovní spoje.","short_t_text":"The slim body combines the heating element, controls and power electronics in a portable tool. The tip delivers heat directly to the joint being soldered. A USB-C connection completes the power solution of this compact soldering iron. The buttons and indicators are located on the top of the pen. Supported settings are available without a separate large station. The shape of the handle lets you guide the tip when working on small electronic joints. The narrow working tip is complemented by a resting stand, as in the version pictured. The portable format brings the necessary parts together in a small set. The tool is intended for small-scale electronics soldering and fine joints.","short_t_html":"\n                            The slim body combines the heating element, controls and power electronics in a portable tool. The tip delivers heat directly to the joint being soldered. A USB-C connection completes the power solution of this compact soldering iron. The buttons and indicators are located on the top of the pen. Supported settings are available without a separate large station. The shape of the handle lets you guide the tip when working on small electronic joints. The narrow working tip is complemented by a resting stand, as in the version pictured. The portable format brings the necessary parts together in a small set. The tool is intended for small-scale electronics soldering and fine joints.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Compact USB-C Soldering Iron for Electronics</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Compact soldering pen</h3><p>The slim body combines the heating element, controls and power electronics in a portable tool. The tip delivers heat directly to the joint being soldered. A USB-C connection completes the power solution of this compact soldering iron.</p><p style=\"margin-top:16px\">The soldering tip forms the working interface between the tool's heating element and the points being joined. Heat transferred into the joint allows you to work with solder on fine wires and electronic leads. The USB-C connector supplies power, whose requirements depend on the specific version of the soldering iron and the power source used.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-017-function-1.jpg\" alt=\"Compact USB-C Soldering Iron for Electronics – Compact soldering pen\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Illustrative depiction of the function</figcaption></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Controls on the tool body</h3><p>The buttons and indicators are located on the top of the pen. Supported settings are available without a separate large station. The shape of the handle lets you guide the tip when working on small electronic joints.</p><p style=\"margin-top:16px\">Placing the controls right on the handle brings the available settings into the tool itself. The indicators provide information about the supported operating state. The soldering pen thus combines the working tip and controls in one portable unit, while the power source and supply cable form the accompanying power setup.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-017-function-2.jpg\" alt=\"Compact USB-C Soldering Iron for Electronics – Controls on the tool body\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Tip and resting stand</h3><p>The narrow working tip is complemented by a resting stand, as in the version pictured. The portable format brings the necessary parts together in a small set. The tool is intended for small-scale electronics soldering and fine joints.</p><p style=\"margin-top:16px\">The shape of the tip concentrates heat transfer on a limited working area. The stand provides a dedicated rest for the tool between individual joints. The overall layout of the set is based on the compact pen format, which keeps the heating element right at your hand and brings in power via the connected cable.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-017-function-3.jpg\" alt=\"Compact USB-C Soldering Iron for Electronics – Tip and resting stand\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Illustrative depiction of the function</figcaption></figure></section></article>\n                            ","params":[["Kategorie:","Měřicí technika a nářadí","Category:","Measuring instruments and tools"],["Kategorie:","Měřicí technika a nářadí","Category:","Measuring instruments and tools"],["Připojení:","USB C","Connection:","USB C"],["Typ produktu:","Kompaktní páječka","Product type:","Compact soldering iron"],["Rozhraní:","USB-C","Interface:","USB-C"],["Určení:","Pájení elektroniky","Intended use:","Soldering electronics"],["Pracovní část:","Pájecí hrot","Working part:","Soldering tip"],["Typické použití:","Vlastní projekty a drobný servis","Typical use:","DIY projects and minor repairs"],["Pracovní prostředí:","Bezpečně připravené pracoviště","Working environment:","Safely prepared workspace"]],"catalog_names":{"Kompaktní USB C páječka":"Compact USB C Soldering Iron","Kompaktní USB-C páječka pro elektroniku":"Compact USB-C Soldering Iron for Electronics"},"catalog_short_cs":"Připravte si kompaktní nástroj pro drobné pájení při stavbě a opravách elektroniky. USB-C páječka se snadno zařadí do vývojářské nebo servisní výbavy a nezabere místo jako velká stolní stanice. Hodí se pro uživatele, kteří chtějí pracovat na vlastních projektech s odpovídajícím napájením a bezpečně připravenou plochou. Konkrétní výkon, hrot a teplotní režimy se řídí dodávanou variantou. Samotný konektor USB-C neurčuje požadavky na napájecí zdroj. Páječku využijete u menších zapojení a servisních úloh, kterým odpovídá její výkon i použitý hrot. Před prací připravte pevný držák, nehořlavou podložku a vhodné větrání.","catalog_short_t":"Get a compact tool ready for small soldering jobs when building and repairing electronics. The USB-C soldering iron fits easily into a developer's or service kit and doesn't take up space like a large bench station. It suits users who want to work on their own projects with an appropriate power supply and a safely prepared work surface. The specific power output, tip and temperature modes depend on the variant supplied. The USB-C connector alone does not determine the power supply requirements. Use the soldering iron for smaller circuits and service tasks that match its power and the tip fitted. Before you start, prepare a sturdy holder, a non-flammable mat and adequate ventilation."},{"code":"OKL-018","name_cs":"Kapesní digitální osciloskop pro měření signálů","name_t":"Pocket Digital Oscilloscope for Signal Measurement","short_cs_text":"Kapesní osciloskop zobrazuje změnu elektrického signálu v čase. Obrazovka kombinuje vykreslený průběh s hodnotami podporovaných měřicích funkcí. Zařízení slouží pro orientaci v signálu, jeho periodě a tvaru při výuce i hobby elektronice. Fyzická tlačítka jsou umístěna vedle displeje pro přístup k měřicím nastavením. Naměřený průběh je dostupný bez notebooku. Kompaktní provedení spojuje vstup měření, zpracování a zobrazení do jednoho přístroje. Výklopná opěra usnadňuje stolní odečet obrazovky. Měřicí vedení připojuje osciloskop k testovanému bodu. Nabíjecí provedení a malé tělo doplňují přenosné použití v rozsahu podporovaného vstupu.","short_t_text":"The pocket oscilloscope shows how an electrical signal changes over time. The screen combines the plotted waveform with readings from the supported measurement functions. The device helps you get to grips with a signal, its period and its shape in teaching and hobby electronics. Physical buttons next to the display give access to the measurement settings. The measured waveform is available without a laptop. The compact design brings the measurement input, processing and display together in a single instrument. A fold-out stand makes it easy to read the screen on a desk. The test lead connects the oscilloscope to the point under test. Rechargeable operation and a small body round off portable use within the range of the supported input.","short_t_html":"\n                            The pocket oscilloscope shows how an electrical signal changes over time. The screen combines the plotted waveform with readings from the supported measurement functions. The device helps you get to grips with a signal, its period and its shape in teaching and hobby electronics. Physical buttons next to the display give access to the measurement settings. The measured waveform is available without a laptop. The compact design brings the measurement input, processing and display together in a single instrument. A fold-out stand makes it easy to read the screen on a desk. The test lead connects the oscilloscope to the point under test. Rechargeable operation and a small body round off portable use within the range of the supported input.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Pocket Digital Oscilloscope for Signal Measurement</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Signal waveform right on the screen</h3><p>The pocket oscilloscope shows how an electrical signal changes over time. The screen combines the plotted waveform with readings from the supported measurement functions. The device helps you get to grips with a signal, its period and its shape in teaching and hobby electronics.</p><p style=\"margin-top:16px\">The horizontal axis of the display represents time, while the vertical axis corresponds to changes in the electrical quantity being monitored. The shape of the trace reveals repetition, pulses or level changes within the capabilities of the instrument. The displayed result depends on the timebase setting, the input sensitivity and the properties of the measured signal.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-018-function-1.jpg\" alt=\"Pocket Digital Oscilloscope for Signal Measurement – Signal waveform right on the screen\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Stand-alone instrument controls</h3><p>Physical buttons next to the display give access to the measurement settings. The measured waveform is available without a laptop. The compact design brings the measurement input, processing and display together in a single instrument.</p><p style=\"margin-top:16px\">The measurement settings determine which part of the signal the screen plots and at what scale. Physical controls give access to the supported adjustments right alongside the displayed trace. Built-in electronics link signal acquisition and processing with the display section, so a basic overview of the signal is produced inside the instrument itself.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-018-function-2.jpg\" alt=\"Pocket Digital Oscilloscope for Signal Measurement – Stand-alone instrument controls\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Stand and portable design</h3><p>A fold-out stand makes it easy to read the screen on a desk. The test lead connects the oscilloscope to the point under test. Rechargeable operation and a small body round off portable use within the range of the supported input.</p><p style=\"margin-top:16px\">The stand holds the screen at an angle, so you can read the waveform without holding the device in your hand. The probe and lead form the electrical path between the input and the circuit under observation. Permissible voltage, frequency range and connection method depend on the specifications of the particular oscilloscope variant.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-018-function-3.jpg\" alt=\"Pocket Digital Oscilloscope for Signal Measurement – Stand and portable design\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Měřicí technika a nářadí","Category","Measuring instruments and tools"],["Kategorie","Měřicí technika a nářadí","Category","Measuring instruments and tools"],["Typ produktu","Digitální osciloskop","Product type","Digital oscilloscope"],["Provedení","Kapesní, přenosné","Design","Pocket-sized, portable"],["Sledovaný obsah","Elektrický průběh v čase","Monitored content","Electrical waveform over time"],["Zobrazení","Digitální displej","Display","Digital display"],["Určení","Základní diagnostika a výuka","Intended for","Basic diagnostics and teaching"],["Použití","V rámci limitů přístroje a sondy","Use","Within the limits of the instrument and probe"]],"catalog_names":{"Kapesní digitální osciloskop pro měření signálů":"Pocket Digital Oscilloscope for Signal Measurement"},"catalog_short_cs":"Podívejte se, jak se elektrický signál mění v čase. Kapesní digitální osciloskop pomáhá při základní diagnostice elektroniky, výuce a ověřování vlastních zapojení. Na obrazovce získáte průběh, který běžné číselné měření nevystihne stejným způsobem. Kompaktní provedení snadno připravíte u pracovního stolu. Před připojením vždy porovnejte úroveň a charakter signálu s povolenými limity přístroje i sondy; použití se řídí skutečným modelem dodávané varianty. Číselná hodnota napětí nemusí říci, zda signál pulzuje nebo jak vypadá jeho tvar. Osciloskop pomůže zobrazit změny v čase a lépe porozumět chování jednoduchého obvodu.","catalog_short_t":"See how an electrical signal changes over time. The pocket digital oscilloscope helps with basic electronics diagnostics, teaching and testing your own circuits. On screen you get a waveform that an ordinary numerical measurement cannot capture in the same way. The compact design is quick to set up at your workbench. Before connecting, always compare the level and nature of the signal with the permitted limits of the instrument and the probe; use is governed by the actual model of the variant supplied. A numerical voltage reading may not tell you whether a signal is pulsing or what its shape looks like. The oscilloscope helps you visualise changes over time and better understand how a simple circuit behaves."},{"code":"OKL-019","name_cs":"Endoskopická kamera USB-C pro inspekci dutin","name_t":"USB-C Endoscope Camera for Cavity Inspection","short_cs_text":"Malá snímací hlava umožňuje nahlédnout do dutin a omezeně přístupných míst. Obraz se přenáší kabelem do kompatibilního zařízení. Konstrukce odděluje místo snímání od obrazovky, na které uživatel sleduje výsledek. Kabelové připojení spojuje kameru s podporovaným telefonem nebo počítačem. USB-C varianta využívá kompatibilní systém a software pro zobrazení obrazu. Ovládací část je umístěna na vedení mezi snímací hlavou a připojovaným zařízením. Světelné prvky v okolí objektivu osvětlují blízký prostor před kamerou. Úzká hlava a ohebné vedení zpřístupňují pohled za kryt nebo do dutiny. Výsledný detail souvisí se vzdáleností povrchu, světlem a ostřicími vlastnostmi kamery.","short_t_text":"A small camera head lets you look into cavities and hard-to-reach places. The image is transmitted via the cable to a compatible device. The design separates the point of capture from the screen on which you view the result. A wired connection links the camera to a supported phone or computer. The USB-C version relies on a compatible operating system and software to display the image. The control unit sits on the cable between the camera head and the connected device. Lights around the lens illuminate the area directly in front of the camera. The slim head and flexible cable let you see behind covers or into cavities. The level of detail depends on the distance from the surface, the lighting and the camera's focusing characteristics.","short_t_html":"\n                            A small camera head lets you look into cavities and hard-to-reach places. The image is transmitted via the cable to a compatible device. The design separates the point of capture from the screen on which you view the result. A wired connection links the camera to a supported phone or computer. The USB-C version relies on a compatible operating system and software to display the image. The control unit sits on the cable between the camera head and the connected device. Lights around the lens illuminate the area directly in front of the camera. The slim head and flexible cable let you see behind covers or into cavities. The level of detail depends on the distance from the surface, the lighting and the camera's focusing characteristics.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>USB-C Endoscope Camera for Cavity Inspection</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Camera at the end of a flexible cable</h3><p>A small camera head lets you look into cavities and hard-to-reach places. The image is transmitted via the cable to a compatible device. The design separates the point of capture from the screen on which you view the result.</p><p style=\"margin-top:16px\">The flexible cable takes the camera section beyond the direct reach of your phone or computer. The camera head captures the area in front of the lens, while the display device stays outside the cavity being inspected. This separation lets you view surfaces beyond the edge of an opening or inside a housing, within the reach of the cable probe.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-019-function-1.jpg\" alt=\"USB-C Endoscope Camera for Cavity Inspection – Camera at the end of a flexible cable\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>USB-C connection</h3><p>A wired connection links the camera to a supported phone or computer. The USB-C version relies on a compatible operating system and software to display the image. The control unit sits on the cable between the camera head and the connected device.</p><p style=\"margin-top:16px\">The physical connector is only one part of the required connection. The image must also be supported by the operating system of the connected device and the display software in use. The cable carries data between the camera section and the host device, which processes the image and shows it on its own screen via a compatible app.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-019-function-2.jpg\" alt=\"USB-C Endoscope Camera for Cavity Inspection – USB-C connection\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Lighting at the camera head</h3><p>Lights around the lens illuminate the area directly in front of the camera. The slim head and flexible cable let you see behind covers or into cavities. The level of detail depends on the distance from the surface, the lighting and the camera's focusing characteristics.</p><p style=\"margin-top:16px\">Close-range lighting supports the camera in spaces that ambient light often fails to reach. Positioning the lights around the lens concentrates the light in the field of view. Shiny surfaces may cause reflections, and getting too close reduces the legibility of detail depending on the focusing range of the particular camera head.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-019-function-3.jpg\" alt=\"USB-C Endoscope Camera for Cavity Inspection – Lighting at the camera head\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Endoskopy a inspekční kamery","Category","Endoscopes and inspection cameras"],["Kategorie","Endoskopy a inspekční kamery","Category","Endoscopes and inspection cameras"],["Připojení","USB-C","Connection","USB-C"],["Typ produktu","Endoskopická inspekční kamera","Product type","Endoscopic inspection camera"],["Přenášený obsah","Obraz","Transmitted content","Image"],["Určení","Vizuální kontrola přístupných dutin","Intended for","Visual inspection of accessible cavities"],["Spolupracující zařízení","Kompatibilní telefon nebo počítač","Compatible devices","Compatible phone or computer"],["Způsob použití","Inspekční sonda","Method of use","Inspection probe"]],"catalog_names":{"Endoskopická kamera USB C":"USB-C Endoscope Camera","Endoskopická kamera USB-C pro inspekci dutin":"USB-C Endoscope Camera for Cavity Inspection"},"catalog_short_cs":"Zkontrolujte místa, kam běžným pohledem nevidíte. Endoskopická kamera USB-C slouží k vizuální prohlídce vhodných dutin, prostoru za nábytkem a přístupných částí mechaniky. Úzká sonda přivede pohled blíž k místu kontroly a obraz zobrazíte na podporovaném zařízení. Hodí se pro domácí údržbu, hledání překážek i orientační kontrolu instalací. Před použitím ověřte kompatibilitu telefonu nebo počítače, požadavky na aplikaci a podmínky, pro které je konkrétní sonda určena. Než začnete rozebírat větší část zařízení, může pomoci obyčejná vizuální kontrola. Inspekční sonda umožňuje prohlédnout dostupné místo a lépe rozhodnout o dalším postupu.","catalog_short_t":"Check places you cannot see with the naked eye. The USB-C endoscope camera is designed for visual inspection of suitable cavities, the space behind furniture and accessible mechanical parts. The slim probe brings your view closer to the spot being checked, and you view the image on a supported device. It is ideal for home maintenance, locating obstructions and quick checks of installations. Before use, check the compatibility of your phone or computer, the app requirements and the conditions the specific probe is designed for. Before you start dismantling a larger part of a device, a simple visual check can help. The inspection probe lets you examine an accessible spot and make a better decision about what to do next."},{"code":"OKL-020","name_cs":"Wi-Fi endoskopická kamera pro inspekční kontrolu","name_t":"Wi-Fi Endoscope Camera for Inspection","short_cs_text":"Wi-Fi modul přenáší obraz z endoskopické kamery do kompatibilní aplikace. Telefon může sloužit jako zobrazovací jednotka oddělená od kabelu se sondou. Tato konstrukce usnadňuje sledování obrazu při manipulaci se snímací hlavou. Kamera je umístěna na konci ohebného vedení. Malá hlava se dostane do míst, kam běžný fotoaparát telefonu nedohlédne. Vedení propojuje sondu s bezdrátovým modulem a přivádí potřebné napájení. Světelné prvky kolem objektivu osvětlují prostor bez samostatné velké lampy. Modul sdružuje bezdrátovou komunikaci a fyzické ovládání podporovaných funkcí. Obraz je určen pro inspekční kontrolu povrchů v dosahu sondy.","short_t_text":"The Wi-Fi module transmits the image from the endoscope camera to a compatible app. Your phone can act as a display unit separate from the probe cable. This design makes it easier to watch the image while manoeuvring the camera head. The camera sits at the end of a flexible cable. The small head reaches places your phone's regular camera cannot see. The cable connects the probe to the wireless module and supplies the necessary power. Lights around the lens illuminate the area without a separate large lamp. The module combines wireless communication with physical controls for the supported functions. The image is intended for inspecting surfaces within reach of the probe.","short_t_html":"\n                            The Wi-Fi module transmits the image from the endoscope camera to a compatible app. Your phone can act as a display unit separate from the probe cable. This design makes it easier to watch the image while manoeuvring the camera head. The camera sits at the end of a flexible cable. The small head reaches places your phone's regular camera cannot see. The cable connects the probe to the wireless module and supplies the necessary power. Lights around the lens illuminate the area without a separate large lamp. The module combines wireless communication with physical controls for the supported functions. The image is intended for inspecting surfaces within reach of the probe.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Wi-Fi Endoscope Camera for Inspection</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Wireless image on your phone</h3><p>The Wi-Fi module transmits the image from the endoscope camera to a compatible app. Your phone can act as a display unit separate from the probe cable. This design makes it easier to watch the image while manoeuvring the camera head.</p><p style=\"margin-top:16px\">The wireless link connects the display part of the set with the endoscope module. The camera head remains attached by its own cable, so wireless transmission applies only to the path between the module and the phone. The app receives the image and provides access to the available functions, depending on device compatibility and the software version used.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-020-function-1.jpg\" alt=\"Wi-Fi Endoscope Camera for Inspection – Wireless image on your phone\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Cable probe for an inspection view</h3><p>The camera sits at the end of a flexible cable. The small head reaches places your phone's regular camera cannot see. The cable connects the probe to the wireless module and supplies the necessary power.</p><p style=\"margin-top:16px\">The cable lets you change the position of the camera head independently of the phone screen. The lens provides a view from the tip of the probe, while the module handles onward transmission. The resulting shot is determined by the position of the head and its optical properties, which affect both the visible area and the legibility of close-up surface details.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-020-function-2.jpg\" alt=\"Wi-Fi Endoscope Camera for Inspection – Cable probe for an inspection view\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Lighting and control module</h3><p>Lights around the lens illuminate the area without a separate large lamp. The module combines wireless communication with physical controls for the supported functions. The image is intended for inspecting surfaces within reach of the probe.</p><p style=\"margin-top:16px\">The lighting and camera together form a single capture unit for environments with limited ambient light. The module separates the power and communication functions from the slim tip of the probe. The set transmits a standard image of the surface in front of the lens, the quality of which depends on distance, lighting and the properties of the material being observed.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-020-function-3.jpg\" alt=\"Wi-Fi Endoscope Camera for Inspection – Lighting and control module\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Endoskopy a inspekční kamery","Category","Endoscopes and inspection cameras"],["Kategorie","Endoskopy a inspekční kamery","Category","Endoscopes and inspection cameras"],["Připojení","Wi-Fi","Connection","Wi-Fi"],["Typ produktu","Endoskopická inspekční kamera","Product type","Endoscopic inspection camera"],["Přenášený obsah","Obraz","Transmitted content","Image"],["Určení","Vizuální kontrola přístupných dutin","Intended for","Visual inspection of accessible cavities"],["Spolupracující zařízení","Kompatibilní mobilní zařízení","Compatible devices","Compatible mobile device"],["Software","Aplikace pro konkrétní kameru","Software","App for the specific camera"]],"catalog_names":{"Endoskopická kamera WiFi":"Wi-Fi Endoscope Camera","Wi-Fi endoskopická kamera pro inspekční kontrolu":"Wi-Fi Endoscope Camera for Inspection"},"catalog_short_cs":"Podívejte se do hůře přístupných míst a zobrazte si obraz na kompatibilním mobilním zařízení. Wi-Fi endoskopická kamera pomáhá s orientační kontrolou dutin, mechaniky a instalací bez přímého datového kabelu do telefonu. Je praktická při domácí údržbě i hledání příčiny obtíží před rozebíráním. Sonda musí rozměry a odolností odpovídat kontrolovanému prostředí. Před prací si vyzkoušejte připojení, aplikaci a zaostření, abyste v samotné dutině věděli, co obraz ukazuje. Pohled dovnitř může pomoci rozhodnout, zda je další zásah potřeba a odkud k němu přistoupit. Sondu zavádějte pomalu a průběžně sledujte směr pohybu.","catalog_short_t":"Look into hard-to-reach places and view the image on a compatible mobile device. The Wi-Fi endoscope camera helps with quick checks of cavities, mechanical parts and installations without a direct data cable to your phone. It is handy for home maintenance and for tracking down the cause of a problem before dismantling anything. The probe's dimensions and durability must suit the environment being inspected. Before you start, test the connection, the app and the focus so that you know what the image is showing once inside the cavity. A look inside can help you decide whether further work is needed and how best to approach it. Insert the probe slowly and keep an eye on the direction of movement."},{"code":"OKL-021","name_cs":"NFC karta pro Google recenze","name_t":"NFC Card for Google Reviews","short_cs_text":"NFC nosič obsahuje odkaz na cílovou stránku s hodnocením firmy. Kompatibilní telefon načte uloženou informaci z malé vzdálenosti a otevře dostupný odkaz. Samotná recenze zůstává rozhodnutím zákazníka na příslušné platformě. Karta nebo stojánkové provedení zpřístupňuje odkaz přímo na místě. Potisk označuje účel NFC plochy a místo pro přiložení telefonu. Nosič slouží k předání odkazu a nevyžaduje vlastní displej. Elektronický čip uchovává podporovaný NFC záznam. Nastavený odkaz propojuje fyzický předmět s online profilem firmy. Pro používání této funkce je potřeba telefon s podporou NFC a možnost otevřít cílovou webovou stránku.","short_t_text":"The NFC tag holds a link to a target page where customers can review your business. A compatible phone reads the stored information at close range and opens the link. Whether to leave a review remains entirely the customer's choice on the relevant platform. The card or stand version makes the link available right on site. The print indicates the purpose of the NFC area and where to tap the phone. The tag simply passes on the link and needs no display of its own. An electronic chip stores a supported NFC record. The configured link connects a physical object with your business's online profile. To use this feature, you need an NFC-enabled phone and the ability to open the target web page.","short_t_html":"\n                            The NFC tag holds a link to a target page where customers can review your business. A compatible phone reads the stored information at close range and opens the link. Whether to leave a review remains entirely the customer's choice on the relevant platform. The card or stand version makes the link available right on site. The print indicates the purpose of the NFC area and where to tap the phone. The tag simply passes on the link and needs no display of its own. An electronic chip stores a supported NFC record. The configured link connects a physical object with your business's online profile. To use this feature, you need an NFC-enabled phone and the ability to open the target web page.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>NFC Card for Google Reviews</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Review link via NFC</h3><p>The NFC tag holds a link to a target page where customers can review your business. A compatible phone reads the stored information at close range and opens the link. Whether to leave a review remains entirely the customer's choice on the relevant platform.</p><p style=\"margin-top:16px\">The transfer passes the stored web link to the phone, leading to the configured business profile or the relevant review page. NFC thus shortens the path between a physical point of contact and the online form. The profile content, user sign-in and the actual submission of the review are handled by the target platform on the phone.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-021-function-1.jpg\" alt=\"NFC Card for Google Reviews – Review link via NFC\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Physical tag for your point of contact</h3><p>The card or stand version makes the link available right on site. The print indicates the purpose of the NFC area and where to tap the phone. The tag simply passes on the link and needs no display of its own.</p><p style=\"margin-top:16px\">The visible design links the service branding with the spot where the phone reads the chip record. The physical format keeps the link accessible without having to show it on a separate display. The card serves as a permanent information carrier, connecting a visit to your premises with the online review environment for your business.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-021-function-2.jpg\" alt=\"NFC Card for Google Reviews – Physical tag for your point of contact\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Writing information to the chip</h3><p>An electronic chip stores a supported NFC record. The configured link connects a physical object with your business's online profile. To use this feature, you need an NFC-enabled phone and the ability to open the target web page.</p><p style=\"margin-top:16px\">The stored record contains information for a compatible NFC reader in the phone. The chip passes on the link, while opening and loading the page takes place on the mobile device. The physical card therefore neither stores reviews nor adds ratings to the profile; it provides a route to the configured online destination.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-021-function-3.jpg\" alt=\"NFC Card for Google Reviews – Writing information to the chip\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Praktické vychytávky","Category","Practical gadgets"],["Kategorie","Praktické vychytávky","Category","Practical gadgets"],["Připojení","NFC","Connection","NFC"],["Typ produktu","NFC karta","Product type","NFC card"],["Účel","Zpřístupnění odkazu pro Google recenze","Purpose","Providing a link to Google reviews"],["Technologie","NFC","Technology","NFC"],["Spolupracující zařízení","Telefon s podporou čtení NFC","Compatible devices","Phone with NFC reading support"],["Cílová služba","Google recenze","Target service","Google reviews"],["Způsob použití","Přiložení kompatibilního telefonu","Method of use","Tapping a compatible phone"]],"catalog_names":{"NFC karta pro Google recenze":"NFC Card for Google Reviews"},"catalog_short_cs":"Usnadněte zákazníkům cestu k hodnocení vašeho podniku. NFC karta může po přiložení kompatibilního telefonu otevřít nastavený odkaz na stránku pro recenzi a omezit zdlouhavé vyhledávání provozovny. Hodí se k recepci, pokladně nebo místu předání služby. Největší smysl má tehdy, když ji nabídnete spokojenému i kritickému zákazníkovi stejně přirozeně a necháte hodnocení na něm. Karta recenzi sama nevytvoří; pouze zpřístupní odpovídající odkaz. Zákazník nemusí ručně hledat správnou pobočku, pokud karta otevírá její konkrétní recenzní stránku. Přiložení telefonu může celý postup zjednodušit na několik běžných kroků.","catalog_short_t":"Make it easier for customers to review your business. When a compatible phone is tapped against it, the NFC card can open a configured link to your review page, saving customers a lengthy search for your premises. It is ideal for a reception desk, checkout or service counter. It works best when you offer it equally naturally to satisfied and critical customers alike and leave the rating up to them. The card does not create a review by itself; it simply provides access to the relevant link. Customers do not have to search manually for the right branch if the card opens that branch's specific review page. Tapping a phone can reduce the whole process to a few simple steps."},{"code":"OKL-022","name_cs":"Mini termotiskárna Bluetooth na poznámky","name_t":"Mini Bluetooth Thermal Printer for Notes","short_cs_text":"Mini tiskárna vytváří obraz zahříváním kompatibilního termopapíru. Tisk proto nevyžaduje klasickou inkoustovou náplň. Výstup slouží pro poznámky, jednoduchou grafiku a další podklady v rozsahu podporovaném aplikací. Telefon předává tiskový obsah prostřednictvím podporovaného bezdrátového připojení. Aplikace připravuje text, obrázek nebo předlohu pro úzký papírový výstup. Rozměry a černobílá technologie určují výslednou podobu vytištěného materiálu. Papír je uložen v těle tiskárny a vystupuje přední štěrbinou. Malá konstrukce sdružuje tiskový mechanismus i zásobu média. Přenosný formát je přizpůsoben krátkým poznámkám a drobným pracovním či studijním výstupům.","short_t_text":"The mini printer creates an image by heating compatible thermal paper. Printing therefore requires no conventional ink cartridge. The output is suitable for notes, simple graphics and other material within the scope supported by the app. Your phone sends the print content via a supported wireless connection. The app prepares text, an image or a template for the narrow paper output. The dimensions and black-and-white technology determine the final appearance of the printed material. The paper is stored inside the printer body and comes out of a slot at the front. The small design houses both the print mechanism and the paper supply. The portable format is tailored to short notes and small outputs for work or study.","short_t_html":"\n                            The mini printer creates an image by heating compatible thermal paper. Printing therefore requires no conventional ink cartridge. The output is suitable for notes, simple graphics and other material within the scope supported by the app. Your phone sends the print content via a supported wireless connection. The app prepares text, an image or a template for the narrow paper output. The dimensions and black-and-white technology determine the final appearance of the printed material. The paper is stored inside the printer body and comes out of a slot at the front. The small design houses both the print mechanism and the paper supply. The portable format is tailored to short notes and small outputs for work or study.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Mini Bluetooth Thermal Printer for Notes</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Thermal printing technology</h3><p>The mini printer creates an image by heating compatible thermal paper. Printing therefore requires no conventional ink cartridge. The output is suitable for notes, simple graphics and other material within the scope supported by the app.</p><p style=\"margin-top:16px\">The print head creates dark dots on the heat-sensitive layer of the paper. These dots combine to form text or a black-and-white image across the width of the supported media. The consumable is a matching paper roll, while the imaging technology itself works without a separate ink cartridge.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-022-function-1.jpg\" alt=\"Mini Bluetooth Thermal Printer for Notes – Thermal printing technology\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Bluetooth and mobile app</h3><p>Your phone sends the print content via a supported wireless connection. The app prepares text, an image or a template for the narrow paper output. The dimensions and black-and-white technology determine the final appearance of the printed material.</p><p style=\"margin-top:16px\">Before printing, the digital template is converted into a form that matches the printer's capabilities. Text and graphics therefore share the same black-and-white output on a narrow strip. Available templates, editing options and the way a job is sent depend on the specific app your phone uses to communicate with the printer.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-022-function-2.jpg\" alt=\"Mini Bluetooth Thermal Printer for Notes – Bluetooth and mobile app\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Compact body and paper roll</h3><p>The paper is stored inside the printer body and comes out of a slot at the front. The small design houses both the print mechanism and the paper supply. The portable format is tailored to short notes and small outputs for work or study.</p><p style=\"margin-top:16px\">The internal roll holder feeds the paper through the print mechanism to the output slot. The assembly keeps the media supply and the working parts in a single body. The finished print takes the form of a narrow strip with content prepared on your phone, with the length and format of each job depending on the capabilities of the app and the media.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-022-function-3.jpg\" alt=\"Mini Bluetooth Thermal Printer for Notes – Compact body and paper roll\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Praktické vychytávky","Category","Practical gadgets"],["Kategorie","Praktické vychytávky","Category","Practical gadgets"],["Připojení","Bluetooth","Connection","Bluetooth"],["Typ produktu","Mini termotiskárna","Product type","Mini thermal printer"],["Technologie tisku","Termální","Printing technology","Thermal"],["Tiskové médium","Kompatibilní termopapír","Print media","Compatible thermal paper"],["Ovládání","Prostřednictvím kompatibilní aplikace","Control","Via a compatible app"],["Určení","Poznámky a menší kreativní výstupy","Intended for","Notes and smaller creative projects"]],"catalog_names":{"Mini termotiskárna Bluetooth":"Mini Bluetooth Thermal Printer","Mini termotiskárna Bluetooth na poznámky":"Mini Bluetooth Thermal Printer for Notes"},"catalog_short_cs":"Přeneste krátké poznámky, jednoduché motivy a pracovní podklady z telefonu na papír. Mini termotiskárna Bluetooth využívá termální tisk bez inkoustových kazet a ovládá se prostřednictvím kompatibilní aplikace. Kompaktní provedení se hodí na pracovní stůl, ke studiu i pro menší kreativní projekty. Výsledek a dostupné šablony se řídí aplikací a vhodným termopapírem. Praktický doplněk, když chcete mít vybrané informace rychle po ruce i mimo obrazovku telefonu. Krátký seznam, jednoduchý obrázek nebo vlastní poznámka mohou mít praktické místo vedle počítače i ve studijním sešitě. Mini tiskárna se zaměřuje právě na takové drobné výstupy.","catalog_short_t":"Transfer short notes, simple designs and work materials from your phone to paper. The mini Bluetooth thermal printer uses thermal printing without ink cartridges and is controlled via a compatible app. Its compact design suits a desk, studying and smaller creative projects. The results and available templates depend on the app and on suitable thermal paper. A handy accessory when you want selected information close at hand, away from your phone screen. A short list, a simple picture or your own note can find a practical place next to your computer or in a study notebook. The mini printer is designed for exactly these kinds of small outputs."},{"code":"OKL-023","name_cs":"Bezdrátový HDMI adaptér pro sdílení obrazu","name_t":"Wireless HDMI Adapter for Screen Sharing","short_cs_text":"Dongle se připojuje do HDMI vstupu kompatibilní televize, monitoru nebo projektoru. Přijímá podporované bezdrátové sdílení obrazu z mobilního zařízení nebo počítače. Jde o přijímač u obrazovky, nikoli o sadu samostatného vysílače a přijímače. Kompatibilní zdroj může sdílet obrazovku, prezentaci nebo podporovaný mediální obsah. Způsob propojení závisí na systému zdrojového zařízení a podporovaném režimu přijímače. Dostupnost přehrávání chráněného obsahu se řídí konkrétní službou a protokolem. Krátké HDMI vedení propojuje kruhové tělo přijímače s obrazovkou. Napájení a nastavení připojení tvoří součást provozu donglu. Malé provedení ponechává hlavní zobrazovací plochu televize nebo monitoru volnou.","short_t_text":"The dongle plugs into the HDMI input of a compatible TV, monitor or projector. It receives supported wireless screen sharing from a mobile device or computer. It is a receiver at the screen end, not a set consisting of a separate transmitter and receiver. A compatible source can share its screen, a presentation or supported media content. The connection method depends on the source device's operating system and the receiver's supported mode. Playback of protected content depends on the specific service and protocol. A short HDMI lead connects the round receiver body to the screen. Power supply and connection setup are part of operating the dongle. The small design keeps the main viewing area of the TV or monitor clear.","short_t_html":"\n                            The dongle plugs into the HDMI input of a compatible TV, monitor or projector. It receives supported wireless screen sharing from a mobile device or computer. It is a receiver at the screen end, not a set consisting of a separate transmitter and receiver. A compatible source can share its screen, a presentation or supported media content. The connection method depends on the source device's operating system and the receiver's supported mode. Playback of protected content depends on the specific service and protocol. A short HDMI lead connects the round receiver body to the screen. Power supply and connection setup are part of operating the dongle. The small design keeps the main viewing area of the TV or monitor clear.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Wireless HDMI Adapter for Screen Sharing</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>HDMI receiver for your screen</h3><p>The dongle plugs into the HDMI input of a compatible TV, monitor or projector. It receives supported wireless screen sharing from a mobile device or computer. It is a receiver at the screen end, not a set consisting of a separate transmitter and receiver.</p><p style=\"margin-top:16px\">The HDMI section passes the received content to the connected display device. The phone or computer is the source of the wireless transmission and must support a compatible sharing mode. The receiver thus creates a link between the wireless content source and a screen that uses a standard wired HDMI input.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-023-function-1.jpg\" alt=\"Wireless HDMI Adapter for Screen Sharing – HDMI receiver for your screen\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Wireless content mirroring</h3><p>A compatible source can share its screen, a presentation or supported media content. The connection method depends on the source device's operating system and the receiver's supported mode. Playback of protected content depends on the specific service and protocol.</p><p style=\"margin-top:16px\">When mirroring, the target screen shows the content sent by the source device. The resulting behaviour is affected by the transmission protocol, the operating system and the specific app. Support for a standard desktop or presentation therefore does not in itself guarantee the availability of every streaming service, whose content may use additional playback protection.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-023-function-2.jpg\" alt=\"Wireless HDMI Adapter for Screen Sharing – Wireless content mirroring\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Compact body with HDMI cable</h3><p>A short HDMI lead connects the round receiver body to the screen. Power supply and connection setup are part of operating the dongle. The small design keeps the main viewing area of the TV or monitor clear.</p><p style=\"margin-top:16px\">The short cable separates the receiver body from the screen connector itself. The receiver electronics stay by the TV, monitor or projector and use an appropriate power supply. The display device takes the image via its HDMI input, while the wireless connection is set up between the source device and the receiver.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-023-function-3.jpg\" alt=\"Wireless HDMI Adapter for Screen Sharing – Compact body with HDMI cable\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Praktické vychytávky","Category","Practical gadgets"],["Kategorie","Praktické vychytávky","Category","Practical gadgets"],["Připojení","HDMI","Connection","HDMI"],["Typ produktu","Bezdrátový HDMI adaptér","Product type","Wireless HDMI adapter"],["Obrazové rozhraní","HDMI","Video interface","HDMI"],["Přenášený obsah","Podporovaný obrazový signál","Transmitted content","Supported video signal"],["Určení","Sdílení obrazu na monitor nebo TV","Intended for","Screen sharing to a monitor or TV"],["Typické použití","Prezentace a domácí multimédia","Typical use","Presentations and home multimedia"],["Kompatibilita","Podle konkrétního přenosového režimu","Compatibility","Depends on the specific transmission mode"]],"catalog_names":{"Bezdrátový HDMI adaptér pro sdílení obrazu":"Wireless HDMI Adapter for Screen Sharing"},"catalog_short_cs":"Přeneste obraz z podporovaného zařízení na větší obrazovku bez dlouhého HDMI kabelu přes místnost. Bezdrátový HDMI adaptér se hodí pro prezentace, sdílení obsahu a domácí multimédia. Při výběru je důležitá kompatibilita zdroje, přijímače a použitého přenosového režimu. Snazší zapojení oceníte tam, kde nechcete pokaždé přestavovat celou pracovní plochu. Rozlišení, latence a podpora streamovacích služeb se řídí konkrétní variantou, nikoli pouze označením HDMI. Prezentaci nebo vybraný obsah lze pohodlněji ukázat na televizi či monitoru než na malém displeji. Adaptér slouží jako součást bezdrátové přenosové cesty a u podporované sestavy omezuje potřebu dlouhého obrazového kabelu.","catalog_short_t":"Send the picture from a supported device to a larger screen without running a long HDMI cable across the room. The wireless HDMI adapter is ideal for presentations, content sharing and home multimedia. When choosing one, compatibility between the source, the receiver and the transmission mode used is key. You will appreciate the simpler set-up wherever you do not want to rearrange your entire workspace every time. Resolution, latency and support for streaming services depend on the specific variant, not merely on the HDMI label. A presentation or selected content can be shown more comfortably on a TV or monitor than on a small display. The adapter forms part of a wireless transmission path and, with a supported set-up, reduces the need for a long video cable."},{"code":"OKL-024","name_cs":"RGB Pixel Clock – LED hodiny na pracovní stůl","name_t":"RGB Pixel Clock – LED Desk Clock","short_cs_text":"RGB Pixel Clock používá několik samostatných barevných zobrazovacích polí. Na jednotlivých částech se mohou zobrazovat číslice nebo podporované obrazové motivy. Výsledkem je členěný digitální panel s výrazným technickým vzhledem. Digitální zobrazení propojuje praktický časový údaj s dekorativním obsahem. Podoba motivů závisí na možnostech konkrétního softwaru a nastavení. Samostatná pole umožňují rozdělit zobrazovaný obsah do vizuálně oddělených částí. Displeje jsou zasazeny do společného podlouhlého těla s průhlednými a kovově působícími částmi. Boční podpěry drží panel na stole. Barevný obraz doplňuje vzhled konstrukce a vytváří samostatný prvek pracovního či herního prostoru.","short_t_text":"The RGB Pixel Clock uses several separate colour display panels. The individual sections can show digits or supported graphic motifs. The result is a segmented digital panel with a striking technical look. The digital display combines a practical time readout with decorative content. The appearance of the motifs depends on the capabilities of the specific software and settings. The separate panels let you divide the displayed content into visually distinct sections. The displays are set in a shared elongated body with transparent and metallic-look parts. Side supports hold the panel upright on the desk. The colourful image complements the look of the design and creates a stand-out feature in your work or gaming space.","short_t_html":"\n                            The RGB Pixel Clock uses several separate colour display panels. The individual sections can show digits or supported graphic motifs. The result is a segmented digital panel with a striking technical look. The digital display combines a practical time readout with decorative content. The appearance of the motifs depends on the capabilities of the specific software and settings. The separate panels let you divide the displayed content into visually distinct sections. The displays are set in a shared elongated body with transparent and metallic-look parts. Side supports hold the panel upright on the desk. The colourful image complements the look of the design and creates a stand-out feature in your work or gaming space.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>RGB Pixel Clock – LED Desk Clock</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Several colour screens side by side</h3><p>The RGB Pixel Clock uses several separate colour display panels. The individual sections can show digits or supported graphic motifs. The result is a segmented digital panel with a striking technical look.</p><p style=\"margin-top:16px\">Dividing the display area creates a row of individually perceived modules instead of a single continuous clock face. Each panel contributes to the overall motif, and the colours highlight the individual parts of the display. With a clock motif, the division can be used for the digits; with supported graphics, for interlinked visual elements.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-024-function-1.jpg\" alt=\"RGB Pixel Clock – LED Desk Clock – Several colour screens side by side\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Time and graphic motifs</h3><p>The digital display combines a practical time readout with decorative content. The appearance of the motifs depends on the capabilities of the specific software and settings. The separate panels let you divide the displayed content into visually distinct sections.</p><p style=\"margin-top:16px\">The appearance of the time readout comes from an electronically generated image. Colour motifs change the look of the panel without swapping any physical digits or front parts. The available content combinations are determined by the firmware and settings of the given version, which links the individual panels into a single display for the digital desk clock.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-024-function-2.jpg\" alt=\"RGB Pixel Clock – LED Desk Clock – Time and graphic motifs\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Desk design with technical details</h3><p>The displays are set in a shared elongated body with transparent and metallic-look parts. Side supports hold the panel upright on the desk. The colourful image complements the look of the design and creates a stand-out feature in your work or gaming space.</p><p style=\"margin-top:16px\">The elongated layout emphasises the rhythm of the display panels and their regular spacing. Transparent parts show off the internal structure, while the supports hold the screens firmly in position relative to one another. The design forms a common base for an electronic clock that also doubles as a colourful decorative panel on your desk.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-024-function-3.jpg\" alt=\"RGB Pixel Clock – LED Desk Clock – Desk design with technical details\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Designové gadgety","Category","Design gadgets"],["Kategorie","Designové gadgety","Category","Design gadgets"],["Model","RGB Pixel Clock","Model","RGB Pixel Clock"],["Typ produktu","Digitální stolní hodiny","Product type","Digital desk clock"],["Označení","RGB Pixel Clock","Designation","RGB Pixel Clock"],["Vzhled zobrazení","Pixelová estetika","Display style","Pixel aesthetic"],["Barevné provedení","RGB motiv","Colour finish","RGB motif"],["Umístění","Pracovní stůl nebo police","Placement","Desk or shelf"],["Úloha v interiéru","Zobrazení času a dekorace","Role in the interior","Time display and decoration"]],"catalog_names":{"LED hodiny RGB Pixel Clock":"RGB Pixel Clock LED Clock","RGB Pixel Clock – LED hodiny na pracovní stůl":"RGB Pixel Clock – LED Desk Clock"},"catalog_short_cs":"Doplňte pracovní stůl nebo herní sestavu o výrazný digitální prvek. Hodiny RGB Pixel Clock spojují zobrazení času s pixelovou estetikou a barevným světlem. Hodí se do interiéru, kde má technika plnit praktickou i dekorativní roli. Při umístění zvažte čitelnost, okolní osvětlení a to, zda chcete mít displej v přímém zorném poli. Dostupné motivy, změny barev a případná aplikace se řídí skutečným modelem dodávané varianty. Digitální hodiny mohou fungovat také jako vizuální doplněk celého pracovního prostoru. Pixelová estetika dobře zapadne vedle elektroniky a vytvoří zajímavý protiklad k běžnému číselníku.","catalog_short_t":"Add a striking digital feature to your desk or gaming set-up. The RGB Pixel Clock combines a time display with a pixel aesthetic and colourful light. It suits interiors where technology is meant to play both a practical and a decorative role. When choosing a spot, consider legibility, ambient lighting and whether you want the display in your direct line of sight. Available motifs, colour changes and any companion app depend on the actual model of the variant supplied. A digital clock can also act as a visual accent for your entire workspace. The pixel aesthetic fits in nicely alongside electronics and makes an interesting contrast to a conventional clock face."},{"code":"OKL-025","name_cs":"Cyberpunk City Lamp – designová LED dekorace","name_t":"Cyberpunk City Lamp – Designer LED Decoration","short_cs_text":"Cyberpunk City Lamp zobrazuje technicky laděnou městskou scénu v kompaktní dekoraci. Vrstvené prvky vytvářejí uličky, výškové úrovně a dojem hloubky. Otevřený pohled dovnitř odhaluje drobné architektonické detaily. Světelné body zvýrazňují jednotlivé části miniatury. Modré a další barevné akcenty navazují na styl nočního futuristického města. Osvětlení je součástí dekorativního efektu modelu. Vnější rám drží prostorovou scénu pohromadě a umožňuje její prohlížení z různých úhlů. Přední a boční pohled odhalují odlišné vrstvy modelu. Dekorace tak kombinuje drobnou architekturu, technické prvky a světelnou atmosféru v jednom stolním objektu.","short_t_text":"The Cyberpunk City Lamp depicts a tech-inspired cityscape in a compact decoration. Layered elements create alleyways, different height levels and a sense of depth. An open view inside reveals tiny architectural details. Points of light highlight individual parts of the miniature. Blue and other coloured accents evoke the style of a futuristic city at night. The lighting is part of the model's decorative effect. An outer frame holds the three-dimensional scene together and lets you view it from different angles. The front and side views reveal different layers of the model. The decoration thus combines miniature architecture, technical elements and an atmospheric glow in a single desktop piece.","short_t_html":"\n                            The Cyberpunk City Lamp depicts a tech-inspired cityscape in a compact decoration. Layered elements create alleyways, different height levels and a sense of depth. An open view inside reveals tiny architectural details. Points of light highlight individual parts of the miniature. Blue and other coloured accents evoke the style of a futuristic city at night. The lighting is part of the model's decorative effect. An outer frame holds the three-dimensional scene together and lets you view it from different angles. The front and side views reveal different layers of the model. The decoration thus combines miniature architecture, technical elements and an atmospheric glow in a single desktop piece.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Cyberpunk City Lamp – Designer LED Decoration</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Three-dimensional city miniature</h3><p>The Cyberpunk City Lamp depicts a tech-inspired cityscape in a compact decoration. Layered elements create alleyways, different height levels and a sense of depth. An open view inside reveals tiny architectural details.</p><p style=\"margin-top:16px\">The individual parts of the scene are arranged at varying distances from the front view. This layering gives the model its three-dimensional character and lets you see smaller objects in the context of the surrounding architecture. Technical shapes and denser detailing echo the look of a futuristic city in a small desktop format.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-025-function-1.jpg\" alt=\"Cyberpunk City Lamp – Designer LED Decoration – Three-dimensional city miniature\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>LED light inside the scene</h3><p>Points of light highlight individual parts of the miniature. Blue and other coloured accents evoke the style of a futuristic city at night. The lighting is part of the model's decorative effect.</p><p style=\"margin-top:16px\">The lighting sets selected details apart from the darker parts of the scene and emphasises its depth. Coloured accents change how edges, openings and the individual architectural layers are perceived. The light is designed primarily to create atmosphere within the miniature and adds another visible element to the model's physical structure.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-025-function-2.jpg\" alt=\"Cyberpunk City Lamp – Designer LED Decoration – LED light inside the scene\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Enclosed piece with multiple views</h3><p>An outer frame holds the three-dimensional scene together and lets you view it from different angles. The front and side views reveal different layers of the model. The decoration thus combines miniature architecture, technical elements and an atmospheric glow in a single desktop piece.</p><p style=\"margin-top:16px\">The three-dimensional design reveals a different arrangement of details as you change your viewing angle. The outer structure frames the scene and defines its compact size. The individual layers remain a mechanical part of the decoration, while the built-in lights highlight the motif and tie the model's architecture to its evening visual effect.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-025-function-3.jpg\" alt=\"Cyberpunk City Lamp – Designer LED Decoration – Enclosed piece with multiple views\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Designové gadgety","Category","Design gadgets"],["Kategorie","Designové gadgety","Category","Design gadgets"],["Model","Cyberpunk City Lamp","Model","Cyberpunk City Lamp"],["Typ produktu","Designová LED dekorace","Product type","Designer LED decoration"],["Označení","Cyberpunk City Lamp","Designation","Cyberpunk City Lamp"],["Vizuální motiv","Futuristické město / sci-fi","Visual theme","Futuristic city / sci-fi"],["Světelná technologie","LED","Lighting technology","LED"],["Umístění","Stůl nebo police v interiéru","Placement","Table or shelf indoors"],["Primární účel","Dekorativní osvětlení","Primary purpose","Decorative lighting"]],"catalog_names":{"LED dekorace Cyberpunk City Lamp":"Cyberpunk City Lamp LED Decoration","Cyberpunk City Lamp – designová LED dekorace":"Cyberpunk City Lamp – Designer LED Decoration"},"catalog_short_cs":"Vytvořte na stole malý světelný akcent inspirovaný futuristickou městskou estetikou. Cyberpunk City Lamp je LED dekorace pro pracovní kout, herní sestavu nebo polici s technickými doplňky. Zaujme především jako atmosférický prvek, který dotváří vzhled interiéru i mimo hlavní osvětlení. Při výběru místa zvažte pohledové strany, přístup k napájení a vztah k ostatním zdrojům světla. Konkrétní režimy a způsob ovládání se řídí dodávanou variantou. Detailní dekorace dokáže změnit dojem z pracovního kouta bez zásahu do celého interiéru. Inspirace městem a sci-fi estetikou se hodí vedle klávesnice, modelů nebo technických sbírek.","catalog_short_t":"Create a small accent of light on your desk, inspired by a futuristic urban aesthetic. The Cyberpunk City Lamp is an LED decoration for a workspace corner, gaming set-up or a shelf of tech accessories. Above all, it stands out as an atmospheric feature that completes the look of a room, even away from the main lighting. When choosing a spot, consider the viewing sides, access to power and how it relates to other light sources. Specific modes and controls depend on the variant supplied. A detailed decoration can change the feel of your workspace without altering the whole interior. Inspired by the city and sci-fi aesthetics, it fits nicely next to a keyboard, models or tech collections."},{"code":"OKL-026","name_cs":"Retro LED hodiny ve stylu Nixie","name_t":"Nixie-Style Retro LED Clock","short_cs_text":"Hodiny rozdělují časový údaj do řady samostatných zobrazovacích prvků. Jejich vzhled odkazuje na historické číslicové výbojky. Jde o moderní elektronické zobrazení ve stylu Nixie, jehož vizuální charakter vytvářejí digitální motivy. Jednotlivé displeje zobrazují barevné číslice a další podporované grafické motivy. Průhledné kryty dávají každému prvku prostorový vzhled. Změna obrazu tak ovlivňuje charakter celého časového panelu. Řada zobrazovacích modulů je upevněna na podlouhlé základně. Ta propojuje elektroniku a drží jednotlivé prvky v rovnoměrných odstupech. Konstrukce kombinuje praktické digitální hodiny s výrazným dekorativním objektem.","short_t_text":"The clock splits the time display into a row of separate display elements. Their appearance pays homage to historic numeric display tubes. This is a modern electronic Nixie-style display whose visual character is created by digital graphics. Each display shows coloured digits and other supported graphic motifs. Transparent covers give every element a three-dimensional look. Changing the image therefore alters the character of the whole time panel. The row of display modules is mounted on an elongated base. It connects the electronics and holds the individual elements at even intervals. The design combines a practical digital clock with a striking decorative piece.","short_t_html":"\n                            The clock splits the time display into a row of separate display elements. Their appearance pays homage to historic numeric display tubes. This is a modern electronic Nixie-style display whose visual character is created by digital graphics. Each display shows coloured digits and other supported graphic motifs. Transparent covers give every element a three-dimensional look. Changing the image therefore alters the character of the whole time panel. The row of display modules is mounted on an elongated base. It connects the electronics and holds the individual elements at even intervals. The design combines a practical digital clock with a striking decorative piece.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Nixie-Style Retro LED Clock</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Individual Nixie-style digits</h3><p>The clock splits the time display into a row of separate display elements. Their appearance pays homage to historic numeric display tubes. This is a modern electronic Nixie-style display whose visual character is created by digital graphics.</p><p style=\"margin-top:16px\">Dividing the time display into separate elements preserves the distinctive look of a row of glowing digits. The electronically generated graphics determine what is actually shown. The retro feel comes from the combination of the cover shapes, the spacing of the individual elements and graphics reminiscent of historic numeric instruments.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-026-function-1.jpg\" alt=\"Nixie-Style Retro LED Clock – Individual Nixie-style digits\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Digital graphics under transparent covers</h3><p>Each display shows coloured digits and other supported graphic motifs. Transparent covers give every element a three-dimensional look. Changing the image therefore alters the character of the whole time panel.</p><p style=\"margin-top:16px\">Each displayed digit is formed by a digital image inside its own module. The transparent cover separates the individual elements and emphasises their height above the base. The colour and design of the motif contribute to the final look of the clock, within the capabilities of the software that controls the individual displays.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-026-function-2.jpg\" alt=\"Nixie-Style Retro LED Clock – Digital graphics under transparent covers\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Shared desktop base</h3><p>The row of display modules is mounted on an elongated base. It connects the electronics and holds the individual elements at even intervals. The design combines a practical digital clock with a striking decorative piece.</p><p style=\"margin-top:16px\">The base unites the row of modules into a single desktop device and keeps them mechanically aligned. The regular spacing helps the separate digits read as a single time display. At the same time, the elongated design keeps each element visually distinct, which is a characteristic part of the decorative look of this type of clock.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-026-function-3.jpg\" alt=\"Nixie-Style Retro LED Clock – Shared desktop base\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Designové gadgety","Category","Design gadgets"],["Kategorie","Designové gadgety","Category","Design gadgets"],["Typ produktu","Stolní digitální hodiny","Product type","Desktop digital clock"],["Vizuální styl","Nixie style","Visual style","Nixie style"],["Světelná technologie","LED","Lighting technology","LED"],["Primární funkce","Zobrazení času","Primary function","Time display"],["Umístění","Pracovní stůl nebo police","Placement","Desk or shelf"],["Konstrukční poznámka","LED stylizace, ne potvrzené výbojky Nixie","Design note","LED styling, not confirmed Nixie tubes"]],"catalog_names":{"Retro LED hodiny Nixie style":"Retro LED Clock, Nixie Style","Retro LED hodiny ve stylu Nixie":"Nixie-Style Retro LED Clock"},"catalog_short_cs":"Propojte vzhled historických číslic s moderním LED provedením. Stolní hodiny ve stylu Nixie jsou výrazným doplňkem pracovního stolu, knihovny nebo interiéru s technickou estetikou. Nabízejí jiný vizuální zážitek než běžný plochý displej a nechávají vyniknout samotné zobrazení času. Jde o LED stylizaci, nikoli automaticky o originální plynové výbojky Nixie. Při výběru místa zvažte čitelnost, okolní světlo a pohodlný přístup k ovládání. Výrazné samostatné číslice připomínají dobu měřicí techniky a prvních elektronických přístrojů. LED pojetí tento vizuální jazyk využívá v dekorativním produktu pro současný interiér.","catalog_short_t":"Combine the look of historic numerals with a modern LED design. The Nixie-style desk clock is a striking addition to a desk, bookshelf or interior with a technical aesthetic. It offers a different visual experience from an ordinary flat display and lets the time display itself take centre stage. This is LED styling, not necessarily genuine Nixie gas-discharge tubes. When choosing a spot, consider readability, ambient light and convenient access to the controls. The bold, separate digits recall the era of measuring equipment and the first electronic instruments. The LED design borrows this visual language for a decorative product suited to contemporary interiors."},{"code":"OKL-027","name_cs":"Ferrofluid Display – magnetická dekorace","name_t":"Ferrofluid Display – Magnetic Decoration","short_cs_text":"Ferrofluid obsahuje jemné magnetické částice rozptýlené v kapalině. Magnetické pole ovlivňuje jeho rozložení a může na povrchu vytvářet výrazné struktury. Změna působení magnetu se projeví přímo v pohybu kapaliny. Průhledná nádoba umožňuje pozorovat přesuny tmavé kapaliny a její rozhraní s okolním prostředím. Kapalina se podle polohy magnetu shlukuje, prodlužuje nebo rozlévá. Zobrazený tvar vzniká fyzikálním působením, nikoli animací na obrazovce. Dekorace zpřístupňuje neobvyklé chování magnetické kapaliny v malém stolním formátu. Skleněná nádoba odděluje kapalinu od okolí a zůstává uzavřená. Tato varianta představuje manuální magnetickou dekoraci bez automatického příslibu reakce na hudbu.","short_t_text":"Ferrofluid contains fine magnetic particles suspended in a liquid. A magnetic field affects its distribution and can form striking structures on its surface. Any change in the magnet's influence shows directly in the movement of the liquid. The transparent container lets you watch the dark liquid move and observe its boundary with the surrounding medium. Depending on the position of the magnet, the liquid clusters, stretches or spreads out. The shape you see is created by physical forces, not by an on-screen animation. The decoration brings the unusual behaviour of a magnetic liquid to a small desktop format. The glass container separates the liquid from its surroundings and remains sealed. This version is a manually operated magnetic decoration and makes no claim to react automatically to music.","short_t_html":"\n                            Ferrofluid contains fine magnetic particles suspended in a liquid. A magnetic field affects its distribution and can form striking structures on its surface. Any change in the magnet's influence shows directly in the movement of the liquid. The transparent container lets you watch the dark liquid move and observe its boundary with the surrounding medium. Depending on the position of the magnet, the liquid clusters, stretches or spreads out. The shape you see is created by physical forces, not by an on-screen animation. The decoration brings the unusual behaviour of a magnetic liquid to a small desktop format. The glass container separates the liquid from its surroundings and remains sealed. This version is a manually operated magnetic decoration and makes no claim to react automatically to music.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Ferrofluid Display – Magnetic Decoration</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Magnetic liquid that responds to a field</h3><p>Ferrofluid contains fine magnetic particles suspended in a liquid. A magnetic field affects its distribution and can form striking structures on its surface. Any change in the magnet's influence shows directly in the movement of the liquid.</p><p style=\"margin-top:16px\">The surface shape results from the combined effect of the magnetic field and the properties of the liquid. As the magnet changes position, the distribution of forces inside the container changes too. The dark fluid thus forms shifting shapes whose appearance depends on the current position of the magnet and the geometry of the sealed space.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-027-function-1.jpg\" alt=\"Ferrofluid Display – Magnetic Decoration – Magnetic liquid that responds to a field\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Illustrative depiction of the function</figcaption></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Changing shapes in a sealed container</h3><p>The transparent container lets you watch the dark liquid move and observe its boundary with the surrounding medium. Depending on the position of the magnet, the liquid clusters, stretches or spreads out. The shape you see is created by physical forces, not by an on-screen animation.</p><p style=\"margin-top:16px\">The transparent walls give a direct view of the real material and how it transforms. The contrast of the dark liquid against its surroundings highlights smaller clusters and changes in their shape. Every movement of the magnet can shift the balance inside the container and create a different spatial structure without any electronically rendered image.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-027-function-2.jpg\" alt=\"Ferrofluid Display – Magnetic Decoration – Changing shapes in a sealed container\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Illustrative depiction of the function</figcaption></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>A hands-on demonstration of magnetism</h3><p>The decoration brings the unusual behaviour of a magnetic liquid to a small desktop format. The glass container separates the liquid from its surroundings and remains sealed. This version is a manually operated magnetic decoration and makes no claim to react automatically to music.</p><p style=\"margin-top:16px\">Manually applying a magnetic field links the visible change to the movement of the magnet. The sealed container keeps the fluid inside and lets you observe its behaviour through the transparent wall. As a whole, it is a physical demonstration of how a material interacts with a magnetic field, with the effect created directly by the liquid moving and rearranging itself.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-027-function-3.jpg\" alt=\"Ferrofluid Display – Magnetic Decoration – A hands-on demonstration of magnetism\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Illustrative depiction of the function</figcaption></figure></section></article>\n                            ","params":[["Kategorie","Designové gadgety","Category","Design gadgets"],["Kategorie","Designové gadgety","Category","Design gadgets"],["Typ produktu","Ferrofluidní dekorace","Product type","Ferrofluid decoration"],["Označení","Ferrofluid Display","Designation","Ferrofluid Display"],["Pracovní médium","Magnetická kapalina – ferrofluid","Working medium","Magnetic liquid – ferrofluid"],["Fyzikální princip","Reakce na magnetické pole","Physical principle","Response to a magnetic field"],["Účel","Dekorace a názorné pozorování","Purpose","Decoration and visual observation"],["Umístění","Stabilní plocha v interiéru","Placement","Stable surface indoors"]],"catalog_names":{"Ferrofluid Display magnetická dekorace":"Ferrofluid Display Magnetic Decoration","Ferrofluid Display – magnetická dekorace":"Ferrofluid Display – Magnetic Decoration"},"catalog_short_cs":"Přidejte pracovnímu stolu drobný fyzikální experiment. Ferrofluid Display využívá magnetickou kapalinu, která při působení magnetického pole mění tvar a vytváří neobvyklé struktury. Hodí se jako dekorace i jako názorný podnět k objevování vlastností magnetismu. Zaujme uživatele, kteří dávají přednost skutečnému fyzikálnímu efektu před běžnou světelnou animací. Způsob ovlivňování kapaliny a konkrétní ovládání se řídí konstrukcí dodávaného výrobku. Ferrofluid obsahuje jemné magnetické částice rozptýlené v kapalině. Při vhodném působení pole se jeho povrch může uspořádat do výrazných struktur.","catalog_short_t":"Add a small physics experiment to your desk. The Ferrofluid Display uses a magnetic liquid that changes shape under the influence of a magnetic field, forming unusual structures. It works both as a decoration and as a hands-on prompt to explore the properties of magnetism. It will appeal to anyone who prefers a genuine physical effect to an ordinary light animation. How the liquid is influenced and the exact controls depend on the design of the product supplied. Ferrofluid contains fine magnetic particles dispersed in a liquid. Under a suitable field, its surface can arrange itself into striking structures."},{"code":"OKL-028","name_cs":"Levitující LED žárovka – magnetická stolní lampa","name_t":"Levitating LED Bulb – Magnetic Table Lamp","short_cs_text":"Magnetické působení udržuje žárovkový světelný prvek nad podstavcem. Mezi oběma částmi zůstává viditelná mezera. Konstrukce tak vytváří skutečný prostorový levitační efekt bez pevného ramene mezi žárovkou a základnou. Průhledná baňka odhaluje světelnou část a doplňuje tvar klasické žárovky. Rozsvícení zvýrazňuje plovoucí objekt i mezeru nad základnou. Lampa slouží jako dekorativní světelný prvek interiéru. Podstavec obsahuje elektroniku pro provoz magnetické sestavy a připojení napájení. Žárovka tvoří oddělenou pohyblivou část. Dřevěně působící povrch základny doplňuje průhledné a kovové části světelného objektu.","short_t_text":"Magnetic force holds the bulb-shaped light element above the base. A visible gap remains between the two parts. The design thus creates a genuine three-dimensional levitation effect with no rigid arm between the bulb and the base. The transparent glass envelope reveals the light source and completes the shape of a classic light bulb. When lit, it highlights both the floating object and the gap above the base. The lamp serves as a decorative interior light feature. The base contains the electronics that operate the magnetic assembly and the power connection. The bulb forms a separate, movable part. The wood-effect surface of the base complements the transparent and metal parts of the light object.","short_t_html":"\n                            Magnetic force holds the bulb-shaped light element above the base. A visible gap remains between the two parts. The design thus creates a genuine three-dimensional levitation effect with no rigid arm between the bulb and the base. The transparent glass envelope reveals the light source and completes the shape of a classic light bulb. When lit, it highlights both the floating object and the gap above the base. The lamp serves as a decorative interior light feature. The base contains the electronics that operate the magnetic assembly and the power connection. The bulb forms a separate, movable part. The wood-effect surface of the base complements the transparent and metal parts of the light object.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Levitating LED Bulb – Magnetic Table Lamp</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>A light element floating above the base</h3><p>Magnetic force holds the bulb-shaped light element above the base. A visible gap remains between the two parts. The design thus creates a genuine three-dimensional levitation effect with no rigid arm between the bulb and the base.</p><p style=\"margin-top:16px\">The levitation assembly balances the forces at work so that the light section stays separate from the base. The visible gap is part of the lamp's actual mechanical arrangement. The bulb element and the base are two separate parts whose relative position defines the character of the whole decorative effect.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-028-function-1.jpg\" alt=\"Levitating LED Bulb – Magnetic Table Lamp – A light element floating above the base\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>LED light in a decorative bulb</h3><p>The transparent glass envelope reveals the light source and completes the shape of a classic light bulb. When lit, it highlights both the floating object and the gap above the base. The lamp serves as a decorative interior light feature.</p><p style=\"margin-top:16px\">The transparent design lets you see the light source inside the bulb while also following its position above the base. The light accentuates the outline of the bulb and the surrounding space. Combining the familiar bulb shape with magnetic suspension creates a desk decoration whose effect relies on the real gap between the parts.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-028-function-2.jpg\" alt=\"Levitating LED Bulb – Magnetic Table Lamp – LED light in a decorative bulb\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Base and power supply</h3><p>The base contains the electronics that operate the magnetic assembly and the power connection. The bulb forms a separate, movable part. The wood-effect surface of the base complements the transparent and metal parts of the light object.</p><p style=\"margin-top:16px\">The power cable leads into the base, which forms the fixed part of the assembly. Its body also defines the area beneath the levitating element and houses the operating electronics. The combination of the fixed base and the separate light section defines the lamp's spatial arrangement and its striking appearance from every angle.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-028-function-3.jpg\" alt=\"Levitating LED Bulb – Magnetic Table Lamp – Base and power supply\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Designové gadgety","Category","Design gadgets"],["Kategorie","Designové gadgety","Category","Design gadgets"],["Typ produktu","Levitující stolní lampa","Product type","Levitating table lamp"],["Světelný prvek","LED žárovka","Light element","LED bulb"],["Princip","Magnetická levitace","Principle","Magnetic levitation"],["Sestava","Základna a levitující část","Assembly","Base and levitating part"],["Primární účel","Dekorativní osvětlení","Primary purpose","Decorative lighting"],["Umístění","Rovná stabilní plocha v interiéru","Placement","Flat, stable surface indoors"]],"catalog_names":{"Levitující LED žárovka magnetická stolní lampa":"Levitating LED Bulb Magnetic Table Lamp","Levitující LED žárovka – magnetická stolní lampa":"Levitating LED Bulb – Magnetic Table Lamp"},"catalog_short_cs":"Světelný bod, který upoutá pozornost i bez výrazných barev. Levitující LED žárovka využívá magnetický princip k vznášení nad základnou a tvoří originální dekorativní prvek interiéru. Hodí se na pracovní stůl, komodu nebo místo, kde může vyniknout její neobvyklé provedení. Při uvádění do provozu je důležité správné usazení a stabilní podklad. Konkrétní způsob napájení, vyvážení a ovládání se řídí dodávanou variantou a jejím návodem. Vizuální efekt vychází z magnetického působení, které při správném nastavení drží světelnou část nad podstavcem. Vzhled se tak liší od běžné lampy s viditelnou podpěrou.","catalog_short_t":"A point of light that catches the eye even without bold colours. The levitating LED bulb uses magnetism to float above its base, creating an original decorative feature for your interior. It suits a desk, a chest of drawers or anywhere its unusual design can stand out. When setting it up, correct positioning and a stable surface are important. The exact power supply, balancing and controls depend on the variant supplied and its instructions. The visual effect is based on magnetic force which, when correctly set up, holds the light section above the base. This makes it look different from an ordinary lamp with a visible support."},{"code":"OKL-029","name_cs":"3D holografický LED ventilátor pro prezentace","name_t":"3D Holographic LED Fan for Presentations","short_cs_text":"LED prvky na pohybujících se ramenech vytvářejí rychle se opakující světelný vzor. Díky setrvačnosti vidění vzniká dojem souvislého obrazu. Tento princip umožňuje zobrazovat motivy a animace s efektem obrazu ve volném prostoru. Řídicí elektronika časuje rozsvěcení LED podle zobrazovaného obsahu. Výsledkem je dvourozměrná světelná plocha s výrazným prostorovým dojmem vhodně připravené grafiky. Nejde o skutečný objemový hologram pozorovatelný stejně ze všech směrů. Zařízení tvoří centrální motorová část a ramena osazená světelnými prvky. Elektronika propojuje pohyb ramen se zobrazovaným vzorem. Otevřená rotující konstrukce je určena pro pevnou instalaci s řešením ochrany odpovídajícím konkrétnímu modelu.","short_t_text":"LED elements on moving blades create a rapidly repeating light pattern. Persistence of vision produces the impression of a continuous image. This principle makes it possible to display motifs and animations that appear to float in mid-air. The control electronics time the switching of the LEDs according to the content being displayed. The result is a two-dimensional light surface that gives suitably prepared graphics a strong sense of depth. It is not a true volumetric hologram visible equally from all directions. The device consists of a central motor unit and blades fitted with light elements. The electronics synchronise the movement of the blades with the displayed pattern. The open rotating design is intended for fixed installation, with protective measures appropriate to the specific model.","short_t_html":"\n                            LED elements on moving blades create a rapidly repeating light pattern. Persistence of vision produces the impression of a continuous image. This principle makes it possible to display motifs and animations that appear to float in mid-air. The control electronics time the switching of the LEDs according to the content being displayed. The result is a two-dimensional light surface that gives suitably prepared graphics a strong sense of depth. It is not a true volumetric hologram visible equally from all directions. The device consists of a central motor unit and blades fitted with light elements. The electronics synchronise the movement of the blades with the displayed pattern. The open rotating design is intended for fixed installation, with protective measures appropriate to the specific model.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>3D Holographic LED Fan for Presentations</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Rotating LEDs for a continuous image</h3><p>LED elements on moving blades create a rapidly repeating light pattern. Persistence of vision produces the impression of a continuous image. This principle makes it possible to display motifs and animations that appear to float in mid-air.</p><p style=\"margin-top:16px\">During rotation, each lit section passes through different points of the display area. Precise timing of the light assembles the individual points into a visible motif. The image is therefore created by a combination of mechanical movement and electronic control, with the viewer perceiving the rapidly repeated light sequence as a whole rather than as separate blades.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-029-function-1.jpg\" alt=\"3D Holographic LED Fan for Presentations – Rotating LEDs for a continuous image\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Illustrative depiction of the function</figcaption></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Animations and custom image motifs</h3><p>The control electronics time the switching of the LEDs according to the content being displayed. The result is a two-dimensional light surface that gives suitably prepared graphics a strong sense of depth. It is not a true volumetric hologram visible equally from all directions.</p><p style=\"margin-top:16px\">Content with a suitable background and shading can strengthen the impression of a standalone object in space. However, the actual display area remains tied to the path of the rotating LEDs. The look of the animation is determined by the prepared file and by the capabilities of the control electronics, which convert image data into timed switching of the individual light points.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-029-function-2.jpg\" alt=\"3D Holographic LED Fan for Presentations – Animations and custom image motifs\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Illustrative depiction of the function</figcaption></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Multi-blade design</h3><p>The device consists of a central motor unit and blades fitted with light elements. The electronics synchronise the movement of the blades with the displayed pattern. The open rotating design is intended for fixed installation, with protective measures appropriate to the specific model.</p><p style=\"margin-top:16px\">The central unit provides the movement, while the blades carry the light points that render the content. Together they form a functional display assembly with moving parts. The mounting method and protective measures depend on the specific model, as the space around the rotating blades is also the device's working area.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-029-function-3.jpg\" alt=\"3D Holographic LED Fan for Presentations – Multi-blade design\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Illustrative depiction of the function</figcaption></figure></section></article>\n                            ","params":[["Kategorie","Designové gadgety","Category","Design gadgets"],["Kategorie","Designové gadgety","Category","Design gadgets"],["Typ produktu","Holografický LED ventilátor","Product type","Holographic LED fan"],["Princip zobrazení","Rotující LED a setrvačnost vidění","Display principle","Rotating LEDs and persistence of vision"],["Zobrazovaný obsah","Podporované animace a obrazové motivy","Displayed content","Supported animations and image motifs"],["Umístění","Vhodná instalace v interiéru","Placement","Suitable indoor installation"],["Účel","Vizuální prezentace a dekorace","Purpose","Visual presentation and decoration"],["Konstrukce","Zařízení s pohybujícími se částmi","Construction","Device with moving parts"]],"catalog_names":{"3D holografický LED ventilátor":"3D Holographic LED Fan","3D holografický LED ventilátor pro prezentace":"3D Holographic LED Fan for Presentations"},"catalog_short_cs":"Vytvořte poutavou vizuální prezentaci, která působí jako obraz ve vzduchu. Holografický LED ventilátor využívá rotující světelné prvky a vhodně připravený obsah k neobvyklému prostorovému dojmu. Uplatní se v interiérové dekoraci, na výstavce nebo při prezentaci produktů. Výsledek závisí na animaci, pozadí a pozici diváka. Před instalací ověřte způsob montáže, ochranu pohybujících se částí a možnosti nahrávání obsahu u konkrétní varianty. Vnímání rychle se opakujícího světelného vzoru umožňuje vytvořit dojem souvislého obrazu. Označení holografický ventilátor se používá pro tento typ prezentace, neznamená však automaticky skutečný objemový hologram viditelný stejně ze všech směrů.","catalog_short_t":"Create an eye-catching visual presentation that looks like an image floating in mid-air. The holographic LED fan uses rotating light elements and suitably prepared content to create an unusual three-dimensional impression. It is ideal for interior decoration, exhibition stands or product presentations. The result depends on the animation, the background and the viewer's position. Before installation, check the mounting method, the protection of moving parts and the content upload options for the specific variant. The perception of a rapidly repeating light pattern creates the impression of a continuous image. The term holographic fan is used for this type of display, but it does not automatically mean a true volumetric hologram visible equally from all directions."},{"code":"OKL-030","name_cs":"WANBO X5 Pro – chytrý Full HD projektor","name_t":"WANBO X5 Pro – Smart Full HD Projector","short_cs_text":"WANBO X5 Pro používá zobrazovací rozlišení 1920 × 1080 pixelů. Projekce přenáší obraz na plátno nebo vhodný povrch a vytváří velkou zobrazovací plochu. Nativní počet pixelů popisuje fyzické rozlišení obrazu projektoru. Automatické zaostření upravuje ostrost promítaného obrazu. Optická část je umístěna na čele zařízení a doplněna elektronickým řízením. Funkce zjednodušuje přípravu projekce při změně polohy projektoru. Projektor propojuje zobrazovací část s podporovanými chytrými funkcemi a vstupy pro obsah. Zadní panel sdružuje konektory a větrací otvory. Široké stolní tělo této edice má tmavé provedení s jemným zlatým akcentem na čelní hraně.","short_t_text":"The WANBO X5 Pro uses a display resolution of 1920 × 1080 pixels. It projects the image onto a screen or suitable surface, creating a large viewing area. The native pixel count describes the projector's physical image resolution. Autofocus adjusts the sharpness of the projected image. The optics sit at the front of the device and are complemented by electronic control. The feature makes setting up the projection easier whenever the projector is moved. The projector combines the display section with supported smart features and content inputs. The rear panel brings together the connectors and ventilation openings. The wide desktop body of this edition has a dark finish with a subtle gold accent on the front edge.","short_t_html":"\n                            The WANBO X5 Pro uses a display resolution of 1920 × 1080 pixels. It projects the image onto a screen or suitable surface, creating a large viewing area. The native pixel count describes the projector's physical image resolution. Autofocus adjusts the sharpness of the projected image. The optics sit at the front of the device and are complemented by electronic control. The feature makes setting up the projection easier whenever the projector is moved. The projector combines the display section with supported smart features and content inputs. The rear panel brings together the connectors and ventilation openings. The wide desktop body of this edition has a dark finish with a subtle gold accent on the front edge.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>WANBO X5 Pro – Smart Full HD Projector</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Native Full HD resolution</h3><p>The WANBO X5 Pro uses a display resolution of 1920 × 1080 pixels. It projects the image onto a screen or suitable surface, creating a large viewing area. The native pixel count describes the projector's physical image resolution.</p><p style=\"margin-top:16px\">The Full HD panel builds the image from a fixed grid of pixels that determines its basic level of detail. The projected image is separate from the body of the device, and its size depends on the projection setup. The legibility of fine details therefore depends on the resolution, focus and conditions on the projection surface.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-030-function-1.jpg\" alt=\"WANBO X5 Pro – Smart Full HD Projector – Native Full HD resolution\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Automatic focus</h3><p>Autofocus adjusts the sharpness of the projected image. The optics sit at the front of the device and are complemented by electronic control. The feature makes setting up the projection easier whenever the projector is moved.</p><p style=\"margin-top:16px\">Focusing adapts the optical image to the distance between the projector and the projection surface. A correctly focused image helps distinguish small text and object edges within the native resolution. Automatic control of this function responds to the device's position and reduces the need to adjust the focus mechanism by hand.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-030-function-2.jpg\" alt=\"WANBO X5 Pro – Smart Full HD Projector – Automatic focus\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Smart playback and connectivity</h3><p>The projector combines the display section with supported smart features and content inputs. The rear panel brings together the connectors and ventilation openings. The wide desktop body of this edition has a dark finish with a subtle gold accent on the front edge.</p><p style=\"margin-top:16px\">The playback system and physical inputs offer different ways of feeding supported content to the projection system. The availability of a specific app or format depends on the features of the edition in question. The ventilation section dissipates heat from the operating electronics, and the rear connectors keep all connections in one part of the body.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-030-function-3.jpg\" alt=\"WANBO X5 Pro – Smart Full HD Projector – Smart playback and connectivity\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Projektory a obraz","Category","Projectors and display"],["Výrobce","WANBO","Manufacturer","WANBO"],["Kategorie","Projektory a obraz","Category","Projectors and display"],["Model","X5 Pro","Model","X5 Pro"],["Rozlišení","Full HD","Resolution","Full HD"],["Typ produktu","Chytrý domácí projektor","Product type","Smart home projector"],["Nativní rozlišení","1920 × 1080 px","Native resolution","1920 × 1080 px"],["Třída rozlišení","Full HD","Resolution class","Full HD"],["Ostření","Automatické","Focus","Automatic"],["Určení","Domácí promítání","Intended use","Home projection"],["Projekční plocha","Vhodná stěna nebo plátno","Projection surface","Suitable wall or screen"]],"catalog_names":{"Chytrý Full HD projektor WANBO X5 Pro":"WANBO X5 Pro Smart Full HD Projector","WANBO X5 Pro – chytrý Full HD projektor":"WANBO X5 Pro – Smart Full HD Projector"},"catalog_short_cs":"Proměňte vybranou stěnu nebo projekční plátno ve větší obraz pro filmy a společné sledování. WANBO X5 Pro spojuje nativní Full HD rozlišení s automatickým ostřením a chytrými funkcemi. Hodí se pro domácí kino, které nechcete omezit na běžnou velikost televizoru. Při umístění zvažte vzdálenost, plochu a okolní světlo. Dostupnost aplikací, rozhraní a přesné parametry posuzujte podle dodávané verze X5 Pro, protože jednotlivé edice nemusejí být shodné. Nativní rozlišení 1920 × 1080 pixelů tvoří základ detailního obrazu při sledování vhodného obsahu. Výsledný dojem ale ovlivňuje také projekční plocha, vzdálenost a zatemnění.","catalog_short_t":"Turn a wall or projection screen into a bigger picture for films and watching together. The WANBO X5 Pro combines native Full HD resolution with autofocus and smart features. It is ideal for a home cinema that you don't want limited to the size of an ordinary TV. When positioning it, consider the distance, the projection surface and ambient light. Check app availability, interfaces and exact specifications against the X5 Pro version supplied, as individual editions may differ. A native resolution of 1920 × 1080 pixels provides the basis for a detailed picture when watching suitable content. The overall impression, however, also depends on the projection surface, the distance and how dark the room is."},{"code":"OKL-031","name_cs":"Retro hodinky s průhledným pouzdrem a digitálním displejem","name_t":"Retro Watch with Transparent Case and Digital Display","short_cs_text":"Hodinky kombinují klasické analogové ručičky s malou digitální částí. Oba způsoby zobrazení jsou umístěny pod společným krycím sklem. Tmavý číselník vytváří kontrast k ručičkám a průhlednému tělu. Fyzická tlačítka jsou dostupná po stranách pouzdra. Slouží k ovládání podporovaných nastavení a funkcí digitální části. Ciferník, elektronika a ovládací prvky tvoří samostatné náramkové zařízení bez nutnosti telefonu. Tvarované pouzdro doplňuje průhledný řemínek s nastavitelným zapínáním. Otevřená struktura materiálu zvýrazňuje technický vzhled hodinek. Řemínek drží ciferník na zápěstí a umožňuje upravit obvod podle polohy přezky.","short_t_text":"The watch combines classic analogue hands with a small digital section. Both displays sit beneath a shared cover glass. The dark dial contrasts with the hands and the transparent case. Physical buttons are located on the sides of the case. They are used to control the supported settings and functions of the digital section. The dial, electronics and controls form a self-contained wristwatch that works without a phone. The shaped case is paired with a transparent strap with an adjustable fastening. The open structure of the material emphasises the watch's technical look. The strap holds the dial on the wrist and lets you adjust the fit using the buckle.","short_t_html":"\n                            The watch combines classic analogue hands with a small digital section. Both displays sit beneath a shared cover glass. The dark dial contrasts with the hands and the transparent case. Physical buttons are located on the sides of the case. They are used to control the supported settings and functions of the digital section. The dial, electronics and controls form a self-contained wristwatch that works without a phone. The shaped case is paired with a transparent strap with an adjustable fastening. The open structure of the material emphasises the watch's technical look. The strap holds the dial on the wrist and lets you adjust the fit using the buckle.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Retro Watch with Transparent Case and Digital Display</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Hands and digital readout on one dial</h3><p>The watch combines classic analogue hands with a small digital section. Both displays sit beneath a shared cover glass. The dark dial contrasts with the hands and the transparent case.</p><p style=\"margin-top:16px\">The analogue section shows the time through the position of the hands, while the digital section displays the available information numerically. Both layers share a single dial and remain visible on the wrist. Together they combine the traditional way of reading the time with an electronic panel whose content depends on the selected watch mode.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-031-function-1.jpg\" alt=\"Retro Watch with Transparent Case and Digital Display – Hands and digital readout on one dial\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Illustrative depiction of the function</figcaption></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Side buttons for control</h3><p>Physical buttons are located on the sides of the case. They are used to control the supported settings and functions of the digital section. The dial, electronics and controls form a self-contained wristwatch that works without a phone.</p><p style=\"margin-top:16px\">Placing the controls on the side leaves the front free for the dial and easy reading. The buttons send commands to the built-in electronics without a touch panel or mobile app. Display modes and settings are changed directly on the watch, according to the functions supported by the specific digital movement.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-031-function-2.jpg\" alt=\"Retro Watch with Transparent Case and Digital Display – Side buttons for control\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Illustrative depiction of the function</figcaption></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Transparent case and strap</h3><p>The shaped case is paired with a transparent strap with an adjustable fastening. The open structure of the material emphasises the watch's technical look. The strap holds the dial on the wrist and lets you adjust the fit using the buckle.</p><p style=\"margin-top:16px\">The translucent parts highlight the outline of the case and the connection between the dial and the strap. The buckle fastening forms an adjustable closed loop around the wrist. The case houses both the display and the controls, while the strap holds it securely in a position suited to checking the time at a glance.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-031-function-3.jpg\" alt=\"Retro Watch with Transparent Case and Digital Display – Transparent case and strap\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Illustrative depiction of the function</figcaption></figure></section></article>\n                            ","params":[["Kategorie","Chytrá elektronika","Category","Smart electronics"],["Kategorie","Chytrá elektronika","Category","Smart electronics"],["Typ produktu","Analogově-digitální náramkové hodinky","Product type","Analogue-digital wristwatch"],["Zobrazení","Ručičky a digitální displej","Display","Hands and digital display"],["Primární funkce","Zobrazení času","Primary function","Time display"],["Způsob nošení","Na zápěstí","Worn on","Wrist"],["Určení","Každodenní spotřební doplněk","Intended use","Everyday consumer accessory"]],"catalog_names":{"Digitální retro hodinky s LED displejem":"Digital Retro Watch with LED Display"},"catalog_short_cs":"Doplňte každodenní výbavu o jednoduchý retro prvek. Digitální hodinky s LED zobrazením staví na číselném odečtu času a výrazné elektronické estetice. Hodí se pro uživatele, kteří dávají přednost nápaditému digitálnímu vzhledu před klasickými ručičkami. Při výběru zvažte pohodlí na zápěstí, čitelnost a způsob aktivace displeje. Další funkce, typ napájení i případná ochrana proti vodě se řídí konkrétním provedením, nikoli pouze obecným označením retro hodinky. Číselný displej připomíná dobu, kdy elektronické hodinky představovaly výraznou změnu oproti tradičnímu ciferníku. Současné provedení může tento styl doplnit do běžného oblečení bez potřeby dalších chytrých funkcí.","catalog_short_t":"Add a simple retro touch to your everyday kit. The digital watch with LED display relies on a numeric time readout and a bold electronic aesthetic. It suits anyone who prefers an inventive digital look to classic hands. When choosing, consider comfort on the wrist, readability and how the display is activated. Additional functions, the type of power supply and any water resistance depend on the specific model, not just the general 'retro watch' label. The numeric display recalls the time when electronic watches were a striking departure from the traditional dial. A modern take can bring this style to everyday outfits without the need for additional smart features."},{"code":"OKL-032","name_cs":"Mini termokamera pro orientační kontrolu","name_t":"Mini Thermal Camera for Indicative Checks","short_cs_text":"Termokamera převádí snímané tepelné záření do barevného obrazu. Různé barvy ukazují rozdíly mezi pozorovanými částmi povrchu. Zobrazení doplňuje běžnou vizuální prohlídku o další informace o zahřívání předmětu. Vestavěný displej ukazuje aktuální teplotní obraz přímo na zařízení. Podporované palety mění způsob barevného rozlišení sledované scény. Samostatné provedení nevyžaduje držet telefon jako hlavní zobrazovací jednotku. Malé tělo soustředí snímací část, displej a ovládání do přenosné kamery. Hodí se pro orientační pozorování tepelných rozdílů na technice i v domácnosti. Údaj se vztahuje k povrchu a závisí také na jeho emisivitě a odrazech okolního záření.","short_t_text":"The thermal camera converts captured thermal radiation into a colour image. Different colours show the differences between the observed parts of a surface. The display adds further information about how an object heats up to an ordinary visual inspection. The built-in display shows the current thermal image directly on the device. Supported palettes change how the observed scene is colour-coded. As a standalone device, it does not require a phone as the main display unit. The small body brings together the sensor, display and controls in a portable camera. It is suitable for indicative observation of temperature differences on equipment and around the home. Readings relate to the surface and also depend on its emissivity and on reflections of ambient radiation.","short_t_html":"\n                            The thermal camera converts captured thermal radiation into a colour image. Different colours show the differences between the observed parts of a surface. The display adds further information about how an object heats up to an ordinary visual inspection. The built-in display shows the current thermal image directly on the device. Supported palettes change how the observed scene is colour-coded. As a standalone device, it does not require a phone as the main display unit. The small body brings together the sensor, display and controls in a portable camera. It is suitable for indicative observation of temperature differences on equipment and around the home. Readings relate to the surface and also depend on its emissivity and on reflections of ambient radiation.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Mini Thermal Camera for Indicative Checks</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Thermal image of the surface</h3><p>The thermal camera converts captured thermal radiation into a colour image. Different colours show the differences between the observed parts of a surface. The display adds further information about how an object heats up to an ordinary visual inspection.</p><p style=\"margin-top:16px\">The thermal sensor captures infrared radiation coming from the observed scene. The electronics convert the available data into an image in which warmer and cooler areas can be distinguished. The output shows the distribution of surface temperature differences within the field of view, and its interpretation also depends on the properties of the specific material.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-032-function-1.jpg\" alt=\"Mini Thermal Camera for Indicative Checks – Thermal image of the surface\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Colour palettes on its own screen</h3><p>The built-in display shows the current thermal image directly on the device. Supported palettes change how the observed scene is colour-coded. As a standalone device, it does not require a phone as the main display unit.</p><p style=\"margin-top:16px\">Colour mapping converts temperature differences into visually distinct shades. The selected palette changes how the same scene is displayed, not the sensing principle itself. The built-in screen combines a view of the object with an instant thermal image reading, keeping the entire display system in a single handheld device.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-032-function-2.jpg\" alt=\"Mini Thermal Camera for Indicative Checks – Colour palettes on its own screen\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Compact handheld design</h3><p>The small body brings together the sensor, display and controls in a portable camera. It is suitable for indicative observation of temperature differences on equipment and around the home. Readings relate to the surface and also depend on its emissivity and on reflections of ambient radiation.</p><p style=\"margin-top:16px\">The handheld camera lets you compare visible thermal areas across different parts of an object. The captured information relates to radiation coming from the surface, so shiny materials may also reflect their surroundings in the image. The camera offers an additional view of operational heating within the limits of its specifications and supported functions.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-032-function-3.jpg\" alt=\"Mini Thermal Camera for Indicative Checks – Compact handheld design\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Měřicí technika a nářadí","Category","Measuring instruments and tools"],["Kategorie","Měřicí technika a nářadí","Category","Measuring instruments and tools"],["Typ produktu","Mini termokamera","Product type","Mini thermal camera"],["Princip","Termální zobrazení povrchů","Principle","Thermal imaging of surfaces"],["Provedení","Kompaktní","Design","Compact"],["Účel","Orientační kontrola teplotních rozdílů","Purpose","Indicative check of temperature differences"],["Pozorovaný objekt","Povrch zařízení nebo materiálu","Observed object","Surface of equipment or material"],["Interpretace","Podle emisivity a okolních podmínek","Interpretation","Depends on emissivity and ambient conditions"]],"catalog_names":{"Mini termokamera":"Mini Thermal Camera","Mini termokamera pro orientační kontrolu":"Mini Thermal Camera for Indicative Checks"},"catalog_short_cs":"Objevte teplotní rozdíly, které běžným pohledem neuvidíte. Mini termokamera se hodí pro orientační kontrolu povrchů, zařízení a míst, která chcete porovnat z hlediska zahřívání. Tepelné zobrazení může pomoci vybrat oblast pro další prověření a lépe dokumentovat rozdíly mezi jednotlivými stavy. Výsledky vždy souvisejí s materiálem, podmínkami a nastavením přístroje. Kompaktní provedení nenahrazuje odborný postup při přesné diagnostice a neznamená pohled skrz stěnu. Teplotní obraz zobrazuje rozdíly, které se při běžné vizuální prohlídce nemusí projevit. Může ukázat místo odlišného zahřívání nebo pomoci porovnat stav před změnou a po ní.","catalog_short_t":"Discover temperature differences you cannot see with the naked eye. The mini thermal camera is suitable for indicative checks of surfaces, equipment and areas you want to compare in terms of heating. Thermal imaging can help you pinpoint an area for further investigation and better document differences between individual states. Results always depend on the material, conditions and device settings. The compact design is no substitute for professional procedures in precise diagnostics and does not let you see through walls. The thermal image shows differences that may not be apparent during an ordinary visual inspection. It can reveal a spot that heats up differently or help compare conditions before and after a change."},{"code":"OKL-033","name_cs":"Univerzální tester elektronických součástek","name_t":"Universal Electronic Component Tester","short_cs_text":"Tester pracuje s vybranými samostatnými elektronickými součástkami. Připojený prvek vyhodnotí v rozsahu podporovaných režimů a výsledek zobrazí na obrazovce. Tato funkce usnadňuje základní třídění a orientační kontrolu drobných dílů. Číselné a grafické údaje na displeji propojují rozpoznaný typ součástky s dostupnými hodnotami. Výsledek je přístupný přímo na přístroji. Vlastní obrazovka a ovládací prvek vytvářejí samostatnou pomůcku pro výuku i hobby elektroniku. Páčková patice usnadňuje připojení vývodů podporovaných součástek. Průhledný kryt ponechává viditelnou desku a současně drží konstrukci přístroje pohromadě. Tester je určen pro odpojené a připravené součástky v přípustném měřicím rozsahu.","short_t_text":"The tester works with selected individual electronic components. It evaluates the connected part within its supported modes and shows the result on the screen. This function makes basic sorting and indicative checks of small parts easier. Numerical and graphical data on the display link the recognised component type with the available values. The result is available directly on the device. Its own screen and control make it a standalone aid for teaching and hobby electronics. The lever socket makes it easier to connect the leads of supported components. The transparent cover leaves the circuit board visible while holding the device together. The tester is intended for disconnected, prepared components within the permitted measuring range.","short_t_html":"\n                            The tester works with selected individual electronic components. It evaluates the connected part within its supported modes and shows the result on the screen. This function makes basic sorting and indicative checks of small parts easier. Numerical and graphical data on the display link the recognised component type with the available values. The result is available directly on the device. Its own screen and control make it a standalone aid for teaching and hobby electronics. The lever socket makes it easier to connect the leads of supported components. The transparent cover leaves the circuit board visible while holding the device together. The tester is intended for disconnected, prepared components within the permitted measuring range.\n                        ","desc_t_html":"\n                <h3>Detailed product description</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Universal Electronic Component Tester</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Identification of supported components</h3><p>The tester works with selected individual electronic components. It evaluates the connected part within its supported modes and shows the result on the screen. This function makes basic sorting and indicative checks of small parts easier.</p><p style=\"margin-top:16px\">The measuring electronics examine the behaviour of the part connected to the test contacts. Based on the supported evaluation, the tester assigns the recognised type and the available characteristic values. The result applies to the connected component in the given test and provides a starting point for identifying parts whose marking or pinout is not obvious at first glance.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-033-function-1.jpg\" alt=\"Universal Electronic Component Tester – Identification of supported components\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Display with measurement results</h3><p>Numerical and graphical data on the display link the recognised component type with the available values. The result is available directly on the device. Its own screen and control make it a standalone aid for teaching and hobby electronics.</p><p style=\"margin-top:16px\">The display combines the identification output with a numerical or graphical description depending on the supported component type. You thus get the measurement result on the same unit to which you connect the component. The electronics and screen form a self-contained unit for basic checks without the need for any computer software.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-033-function-2.jpg\" alt=\"Universal Electronic Component Tester – Display with measurement results\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Test socket and transparent body</h3><p>The lever socket makes it easier to connect the leads of supported components. The transparent cover leaves the circuit board visible while holding the device together. The tester is intended for disconnected, prepared components within the permitted measuring range.</p><p style=\"margin-top:16px\">The socket creates a detachable connection between the component leads and the measuring electronics. The lever mechanism lets you secure the leads without permanent soldering. The transparent housing combines a view of the board with mechanical protection for the device, while the available contacts determine how parts are connected for each supported test.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-033-function-3.jpg\" alt=\"Universal Electronic Component Tester – Test socket and transparent body\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Měřicí technika a nářadí","Category","Measuring instruments and tools"],["Kategorie","Měřicí technika a nářadí","Category","Measuring instruments and tools"],["Typ produktu","Tester elektronických součástek","Product type","Electronic component tester"],["Provedení","Stolní / přenosná měřicí pomůcka","Design","Benchtop / portable measuring aid"],["Zobrazení výsledku","Digitální","Result display","Digital"],["Účel","Kontrola podporovaných součástek","Purpose","Checking supported components"],["Typické použití","Výuka, třídění a hobby elektronika","Typical use","Teaching, sorting and hobby electronics"],["Příprava měření","Odpojená součástka, vybité kondenzátory","Measurement preparation","Disconnected component, discharged capacitors"]],"catalog_names":{"Univerzální tester elektronických součástek":"Universal Electronic Component Tester"},"catalog_short_cs":"Zorientujte se rychleji v podporovaných součástkách pro vlastní elektronické projekty. Univerzální tester pomáhá s jejich kontrolou a vyhodnocením v rozsahu funkcí konkrétního přístroje. Využijete ho při výuce, třídění materiálu i přípravě zapojení na pracovním stole. Důležitý je správný výběr kontaktů, práce s odpojenou součástkou a respektování měřicích limitů. Výsledky berte jako praktickou pomůcku, kterou u přesné aplikace doplníte dokumentací a případně dalším měřením. Při přípravě projektu se snadno sejde více podobně vypadajících prvků. Tester může pomoci u podporovaných typů a zjednodušit první orientaci.","catalog_short_t":"Get to grips with supported components faster in your own electronics projects. The universal tester helps you check and evaluate them within the functions of the specific device. Use it for teaching, sorting parts and preparing circuits on your workbench. What matters is choosing the right contacts, working with a disconnected component and respecting the measurement limits. Treat the results as a practical aid which, for precise applications, you should supplement with documentation and, where appropriate, further measurements. When preparing a project, it is easy to end up with several similar-looking parts. The tester can help with supported types and make initial identification easier."}];
